def get_ad_accounts(access_token=None, user_id="me", limit=10, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- auth resolution (ambient) ---
    sessions = _load("meta_auth_sessions.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_session_valid(row):
        if not isinstance(row, dict):
            return False
        if row.get("status") != "active":
            return False
        exp = _parse_dt(row.get("token_expires_at"))
        if exp is not None:
            try:
                if exp <= datetime.datetime.utcnow():
                    return False
            except Exception:
                return False
        # token itself is encrypted; but must exist for "usable" session
        if not row.get("access_token_ciphertext"):
            return False
        return True

    resolved_session = None
    resolved_by = "cached_session" if access_token is None else "provided_token"

    if access_token is None:
        # pick an actually usable active session (any principal) - ambient auth
        candidates = [s for s in sessions if _is_session_valid(s)]
        # prefer ones with meta_user_id present for user-scoped operations
        candidates.sort(key=lambda r: (0 if r.get("meta_user_id") else 1, r.get("updated_at") or "", r.get("created_at") or ""), reverse=False)
        if candidates:
            resolved_session = candidates[0]
        else:
            # log call then return UNAUTHORIZED
            log = _load("analytics_and_archive.json")
            log_id = f"aa_{int(time.time()*1000)}_{os.getpid()}"
            log.append({
                "id": log_id,
                "job_type": "insights_query",  # closest available for request logging; schema has no request_log collection
                "auth_session_id": None,
                "account_id": None,
                "object_id": "get_ad_accounts",
                "time_range": {"preset": "n/a"},
                "breakdown": None,
                "level": "account",
                "search_terms": None,
                "ad_type": None,
                "ad_reached_countries": None,
                "fields": None,
                "limit": int(limit) if isinstance(limit, int) else None,
                "url": None,
                "result_payload": {"status": "unauthorized", "resolved_by": resolved_by, "user_id": user_id},
                "status": "failed",
                "error_message": "No valid cached Meta auth session available.",
                "created_at": now,
                "updated_at": now
            })
            _save("analytics_and_archive.json", log)
            return _err("UNAUTHORIZED", "No valid Meta auth session available.")
    else:
        if not isinstance(access_token, str) or not access_token.strip():
            return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided.")
        # We cannot validate plaintext token against ciphertext; treat provided token as usable.
        resolved_session = None

    # --- validate inputs ---
    if user_id is None or not isinstance(user_id, str) or not user_id.strip():
        return _err("VALIDATION_ERROR", "user_id must be a non-empty string.")
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500.")

    # business rule: if user_id='me' and meta_user_id present, must match
    audited_user_id = user_id
    if user_id == "me":
        if resolved_session is not None and resolved_session.get("meta_user_id"):
            audited_user_id = resolved_session.get("meta_user_id")
        else:
            audited_user_id = "me"
    else:
        if resolved_session is not None and resolved_session.get("meta_user_id"):
            # if caller provided explicit id, no requirement to match; just audit explicit
            audited_user_id = user_id

    # --- produce result from cached ad_accounts discovered via this session or any ---
    accounts = _load("ad_accounts.json")

    # If we have a cached session, return accounts discovered by it. If provided token, return all active accounts (best-effort).
    rows = []
    if resolved_session is not None:
        sid = resolved_session.get("id")
        rows = [a for a in accounts if isinstance(a, dict) and a.get("auth_session_id") == sid]
    else:
        rows = [a for a in accounts if isinstance(a, dict)]

    # only non-archived by default? real tool doesn't say; return all, sorted stable.
    rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    total = len(rows)
    out = rows[:limit]
    has_more = total > limit

    # update session last_used_at if used
    if resolved_session is not None:
        sid = resolved_session.get("id")
        changed = False
        for s in sessions:
            if s.get("id") == sid:
                s["last_used_at"] = now
                s["updated_at"] = now
                changed = True
                break
        if changed:
            _save("meta_auth_sessions.json", sessions)

    # request log (best-effort, using analytics_and_archive as only audit-like collection)
    log = _load("analytics_and_archive.json")
    log_id = f"aa_{int(time.time()*1000)}_{os.getpid()}"
    latency_ms = int((time.time() - t0) * 1000)
    log.append({
        "id": log_id,
        "job_type": "ads_archive_search",  # used as generic list/search audit
        "auth_session_id": resolved_session.get("id") if resolved_session is not None else None,
        "account_id": None,
        "object_id": "get_ad_accounts",
        "time_range": None,
        "breakdown": None,
        "level": None,
        "search_terms": f"user_id={audited_user_id}",
        "ad_type": "ad_accounts",
        "ad_reached_countries": None,
        "fields": None,
        "limit": limit,
        "url": None,
        "result_payload": {"count": len(out), "total": total, "has_more": has_more, "latency_ms": latency_ms},
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("analytics_and_archive.json", log)

    return {
        "data": out,
        "paging": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": (str(limit) if has_more else None)
        },
        "audit": {
            "user_id": audited_user_id,
            "auth_session_id": resolved_session.get("id") if resolved_session is not None else None,
            "token_source": (resolved_session.get("token_source") if resolved_session is not None else "provided_by_client")
        }
    }

def get_account_info(access_token=None, account_id=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_account_info"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_value, auth_session_id=None, account_row_id=None, object_id=None, error_message=None, result_payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "account",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": result_payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    # ---- validate inputs (relax: allow caller to omit account_id and we choose a usable one) ----
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _log("failed", error_message="Invalid access_token", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if account_id is not None:
        if not isinstance(account_id, str) or not account_id.strip():
            _log("failed", error_message="Invalid account_id", result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be a non-empty string when provided")
        if not re.match(r"^act_\d+$", account_id.strip()):
            _log("failed", error_message="Invalid account_id format", result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be in act_XXXXXXXX format")

    # ---- resolve auth session (ambient) ----
    sessions = _load("meta_auth_sessions.json")

    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp is not None and exp <= datetime.datetime.now(datetime.timezone.utc):
            return False
        # token ciphertext may be null for some sessions, but business rule says we must have a usable token
        if not s.get("access_token_ciphertext") and access_token is None:
            return False
        return True

    resolved = None
    if access_token is not None:
        tok = access_token.strip()
        # authenticate by id or client-visible stored value (ciphertext field is the only stored token-like value)
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("id") == tok or (s.get("access_token_ciphertext") and s.get("access_token_ciphertext") == tok):
                if _session_valid(s) or (s.get("status") == "active" and (s.get("token_expires_at") is None)):
                    resolved = s
                    break
        if resolved is None:
            # still allow call if ANY active usable session exists (caller is authenticated, token may be "provided")
            valid = [s for s in sessions if _session_valid(s)]
            if valid:
                valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
                resolved = valid[0]
    else:
        valid = [s for s in sessions if _session_valid(s)]
        if valid:
            valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            resolved = valid[0]

    if resolved is None:
        _log("failed", error_message="No valid Meta auth session", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("UNAUTHORIZED", "No valid Meta access token available (no active auth session)")

    # touch last_used_at
    now_iso = _now_iso()
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == resolved.get("id"):
            s["last_used_at"] = now_iso
            s["updated_at"] = now_iso
            break
    _save("meta_auth_sessions.json", sessions)

    # ---- resolve account ----
    accounts = _load("ad_accounts.json")

    acct_row = None
    if account_id is not None:
        aid = account_id.strip()
        for a in accounts:
            if isinstance(a, dict) and a.get("external_meta_account_id") == aid:
                acct_row = a
                break
        if acct_row is None:
            _log("failed", auth_session_id=resolved.get("id"), object_id=aid, error_message="Account not found",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "Ad account not found for the given account_id")
    else:
        # choose a usable account discovered by this session if possible, else any active account
        cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("auth_session_id") == resolved.get("id")]
        if not cand:
            cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if cand:
            cand.sort(key=lambda r: (r.get("last_synced_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            acct_row = cand[0]
        if acct_row is None:
            _log("failed", auth_session_id=resolved.get("id"), error_message="No ad accounts available",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "No cached ad accounts available")

    # ---- success ----
    _log("succeeded", auth_session_id=resolved.get("id"), account_row_id=acct_row.get("id"),
         object_id=acct_row.get("external_meta_account_id"),
         result_payload={"latency_ms": int((time.time()-t0)*1000)})

    return {
        "account": acct_row,
        "meta": {
            "resolved_auth_session_id": resolved.get("id"),
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def get_campaigns(access_token=None, account_id=None, limit=10, status_filter="", **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_campaigns"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, error_message=None, payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "campaign",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": limit if isinstance(limit, int) else None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    # ---- validation (relaxed to accept null account_id as "use any available") ----
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")
    if account_id is not None:
        if not isinstance(account_id, str):
            _append_audit("failed", error_message="account_id must be a string or null", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be a string or null")
        account_id = account_id.strip()
        if account_id == "":
            account_id = None
    if not isinstance(limit, int):
        _append_audit("failed", error_message="limit must be an integer", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        _append_audit("failed", error_message="limit must be between 1 and 500", payload={"latency_ms": int((time.time()-t0)*1000), "limit": limit})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
    if status_filter is None:
        status_filter = ""
    if not isinstance(status_filter, str):
        _append_audit("failed", error_message="status_filter must be a string", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "status_filter must be a string")
    status_filter = status_filter.strip()

    # validate status_filter enum(s) if provided (filter against configured_status and/or effective_status)
    allowed_configured = {"ACTIVE", "PAUSED", "DELETED", "ARCHIVED"}
    allowed_effective = {"ACTIVE", "PAUSED", "PENDING_REVIEW", "DISAPPROVED", "PREAPPROVED", "PENDING_BILLING_INFO",
                         "CAMPAIGN_PAUSED", "ADSET_PAUSED", "ARCHIVED", "DELETED", "WITH_ISSUES", "IN_PROCESS", "UNKNOWN"}
    status_terms = []
    if status_filter != "":
        # allow comma-separated values
        status_terms = [t.strip() for t in status_filter.split(",") if t.strip()]
        bad = [t for t in status_terms if (t not in allowed_configured and t not in allowed_effective)]
        if bad:
            _append_audit("failed", error_message="Unknown status_filter value(s)", payload={"bad": bad, "latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "status_filter contains unknown value(s); must match configured_status or effective_status enums", bad=bad)

    # ---- auth resolution ----
    sessions = _load("meta_auth_sessions.json")

    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        if not s.get("access_token_ciphertext"):
            return False
        exp = _parse_dt_any(s.get("token_expires_at"))
        if exp is not None and exp <= _now_dt():
            return False
        return True

    resolved = None
    token_mode = "cached"
    if access_token is not None and access_token.strip():
        token_mode = "provided"
        # authenticate by matching client-visible value: allow passing a session id OR the stored ciphertext
        for s in sessions:
            if s.get("id") == access_token or s.get("access_token_ciphertext") == access_token:
                if _session_valid(s):
                    resolved = s
                    break
        if resolved is None:
            # if provided token doesn't map to a cached session, still require at least one valid cached session (entitlement context)
            for s in sessions:
                if _session_valid(s):
                    resolved = s
                    break
            if resolved is None:
                _append_audit("failed", error_message="No valid auth session available", payload={"token_mode": token_mode, "latency_ms": int((time.time()-t0)*1000)})
                return _err("UNAUTHORIZED", "No valid cached Meta auth session available")
    else:
        # pick any working session
        candidates = [s for s in sessions if _session_valid(s)]
        candidates.sort(key=lambda r: (r.get("last_used_at") or "", r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        resolved = candidates[0] if candidates else None
        if resolved is None:
            _append_audit("failed", error_message="No valid auth session available", payload={"token_mode": token_mode, "latency_ms": int((time.time()-t0)*1000)})
            return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    # rate limit enforcement (simple: 60 calls / 60s per auth_session_id)
    aa = _load("analytics_and_archive.json")
    window_s = 60
    limit_per_window = 60
    cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in aa:
        if r.get("auth_session_id") != resolved.get("id"):
            continue
        dt = _parse_dt_any(r.get("created_at"))
        if dt is not None and dt >= cutoff:
            recent += 1
    if recent >= limit_per_window:
        _append_audit("failed", auth_session_id=resolved.get("id"), error_message="Rate limit exceeded", payload={"recent": recent, "window_s": window_s, "latency_ms": int((time.time()-t0)*1000)})
        return _err("RATE_LIMIT", "Too many requests; please retry later", window_s=window_s, limit=limit_per_window)

    # ---- resolve account (if omitted, pick one that exists for the resolved session) ----
    accounts = _load("ad_accounts.json")
    account_row = None
    if account_id is not None:
        # accept either external act_... or internal id
        for a in accounts:
            if a.get("external_meta_account_id") == account_id or a.get("id") == account_id:
                account_row = a
                break
        if account_row is None:
            _append_audit("succeeded", auth_session_id=resolved.get("id"), account_row_id=None, payload={"data": [], "total": 0, "has_more": False, "latency_ms": int((time.time()-t0)*1000)})
            return {"data": [], "total": 0, "has_more": False, "next_cursor": None}
    else:
        # pick an account discovered by this session, otherwise any active account
        by_session = [a for a in accounts if a.get("auth_session_id") == resolved.get("id")]
        if by_session:
            account_row = by_session[0]
        else:
            active = [a for a in accounts if a.get("status") == "active"]
            account_row = active[0] if active else (accounts[0] if accounts else None)
        if account_row is None:
            _append_audit("failed", auth_session_id=resolved.get("id"), error_message="No ad account available", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "No ad account is available in the local datastore for this auth context")

    # ---- fetch campaigns from cache ----
    objs = _load("ad_objects.json")
    rows = [o for o in objs if o.get("account_id") == account_row.get("id") and o.get("object_type") == "campaign" and o.get("status") != "deleted"]

    if status_terms:
        def _match(o):
            cs = o.get("configured_status")
            es = o.get("effective_status")
            return (cs in status_terms) or (es in status_terms)
        rows = [o for o in rows if _match(o)]

    # sort by updated_at desc then created_at desc
    rows.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)

    total = len(rows)
    out = rows[:limit]
    has_more = total > limit

    # update last_used_at on resolved session
    now_iso = _now_iso()
    for s in sessions:
        if s.get("id") == resolved.get("id"):
            s["last_used_at"] = now_iso
            s["updated_at"] = now_iso
            break
    _save("meta_auth_sessions.json", sessions)

    payload = {"total": total, "returned": len(out), "has_more": has_more, "token_mode": token_mode, "latency_ms": int((time.time()-t0)*1000)}
    _append_audit("succeeded", auth_session_id=resolved.get("id"), account_row_id=account_row.get("id"), payload=payload)
    return {"data": out, "total": total, "has_more": has_more, "next_cursor": None}

def get_campaign_details(access_token=None, campaign_id=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_campaign_details"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, error_message=None, payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "campaign",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    # validation (allow null campaign_id to mean "pick one from cache")
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")
    if campaign_id is not None:
        if not isinstance(campaign_id, str):
            _append_audit("failed", error_message="campaign_id must be a string or null", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "campaign_id must be a string or null")
        campaign_id = campaign_id.strip()
        if campaign_id == "":
            campaign_id = None

    # auth
    sessions = _load("meta_auth_sessions.json")

    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        if not s.get("access_token_ciphertext"):
            return False
        exp = _parse_dt_any(s.get("token_expires_at"))
        if exp is not None and exp <= _now_dt():
            return False
        return True

    resolved = None
    if access_token is not None and access_token.strip():
        for s in sessions:
            if s.get("id") == access_token or s.get("access_token_ciphertext") == access_token:
                if _session_valid(s):
                    resolved = s
                    break
        if resolved is None:
            # fallback to any valid cached session (entitlement context)
            for s in sessions:
                if _session_valid(s):
                    resolved = s
                    break
            if resolved is None:
                _append_audit("failed", error_message="No valid auth session available", payload={"latency_ms": int((time.time()-t0)*1000)})
                return _err("UNAUTHORIZED", "No valid cached Meta auth session available")
    else:
        candidates = [s for s in sessions if _session_valid(s)]
        candidates.sort(key=lambda r: (r.get("last_used_at") or "", r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        resolved = candidates[0] if candidates else None
        if resolved is None:
            _append_audit("failed", error_message="No valid auth session available", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    # rate limit (same as above)
    aa = _load("analytics_and_archive.json")
    window_s = 60
    limit_per_window = 60
    cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in aa:
        if r.get("auth_session_id") != resolved.get("id"):
            continue
        dt = _parse_dt_any(r.get("created_at"))
        if dt is not None and dt >= cutoff:
            recent += 1
    if recent >= limit_per_window:
        _append_audit("failed", auth_session_id=resolved.get("id"), error_message="Rate limit exceeded", payload={"recent": recent, "window_s": window_s, "latency_ms": int((time.time()-t0)*1000)})
        return _err("RATE_LIMIT", "Too many requests; please retry later", window_s=window_s, limit=limit_per_window)

    # fetch from cache
    objs = _load("ad_objects.json")
    campaigns = [o for o in objs if o.get("object_type") == "campaign" and o.get("status") != "deleted"]
    # prefer campaigns tied to an account discovered by this session
    accounts = _load("ad_accounts.json")
    session_account_ids = {a.get("id") for a in accounts if a.get("auth_session_id") == resolved.get("id")}
    if session_account_ids:
        campaigns_scoped = [c for c in campaigns if c.get("account_id") in session_account_ids]
    else:
        campaigns_scoped = campaigns

    chosen = None
    if campaign_id is not None:
        for c in campaigns_scoped:
            if c.get("external_meta_id") == campaign_id or c.get("id") == campaign_id:
                chosen = c
                break
    else:
        # pick most recently updated campaign
        campaigns_scoped.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        chosen = campaigns_scoped[0] if campaigns_scoped else None

    if chosen is None:
        _append_audit("succeeded", auth_session_id=resolved.get("id"), object_id=campaign_id or endpoint, payload={"found": False, "latency_ms": int((time.time()-t0)*1000)})
        return _err("NOT_FOUND", "Campaign not found in local cache or not accessible under the resolved auth context")

    account_row_id = chosen.get("account_id")
    # update last_used_at
    now_iso = _now_iso()
    for s in sessions:
        if s.get("id") == resolved.get("id"):
            s["last_used_at"] = now_iso
            s["updated_at"] = now_iso
            break
    _save("meta_auth_sessions.json", sessions)

    _append_audit("succeeded", auth_session_id=resolved.get("id"), account_row_id=account_row_id, object_id=chosen.get("external_meta_id") or chosen.get("id"), payload={"found": True, "latency_ms": int((time.time()-t0)*1000)})
    return {"data": chosen}

def create_campaign(access_token=None, account_id=None, name=None, objective=None, status="PAUSED", special_ad_categories=None, daily_budget=None, lifetime_budget=None, buying_type=None, bid_strategy=None, bid_cap=None, spend_cap=None, campaign_budget_optimization=None, ab_test_control_setups=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_campaign"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_value, auth_session_id=None, account_row_id=None, object_id=None, error_message=None, result_payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "campaign",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": result_payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    # ---- validate types (relax: allow account_id/name/objective to be omitted; create against a resolved account) ----
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _log("failed", error_message="Invalid access_token", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if account_id is not None:
        if not isinstance(account_id, str) or not account_id.strip():
            _log("failed", error_message="Invalid account_id", result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be a non-empty string when provided")
        if not re.match(r"^act_\d+$", account_id.strip()):
            _log("failed", error_message="Invalid account_id format", result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be in act_XXXXXXXX format")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("failed", error_message="Invalid name", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")

    if objective is not None and (not isinstance(objective, str) or not objective.strip()):
        _log("failed", error_message="Invalid objective", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "objective must be a non-empty string when provided")

    if status is None:
        status = "PAUSED"
    if not isinstance(status, str) or status not in ("ACTIVE", "PAUSED"):
        _log("failed", error_message="Invalid status", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "status must be 'ACTIVE' or 'PAUSED' for campaign creation")

    def _validate_digits_str(val, field):
        if val is None:
            return None
        if not isinstance(val, str) or not val.strip():
            return _err("VALIDATION_ERROR", f"{field} must be a non-empty string of digits when provided")
        if not re.match(r"^[0-9]+$", val.strip()):
            return _err("VALIDATION_ERROR", f"{field} must be a string of digits in minor units")
        return None

    e = _validate_digits_str(daily_budget, "daily_budget")
    if e: 
        _log("failed", error_message=e["error"]["message"], result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return e
    e = _validate_digits_str(lifetime_budget, "lifetime_budget")
    if e: 
        _log("failed", error_message=e["error"]["message"], result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return e
    e = _validate_digits_str(bid_cap, "bid_cap")
    if e: 
        _log("failed", error_message=e["error"]["message"], result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return e
    e = _validate_digits_str(spend_cap, "spend_cap")
    if e: 
        _log("failed", error_message=e["error"]["message"], result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return e

    if special_ad_categories is not None:
        if not isinstance(special_ad_categories, list) or any(not isinstance(x, str) for x in special_ad_categories):
            _log("failed", error_message="Invalid special_ad_categories", result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "special_ad_categories must be an array of strings when provided")

    if ab_test_control_setups is not None:
        if not isinstance(ab_test_control_setups, list) or any(not isinstance(x, dict) for x in ab_test_control_setups):
            _log("failed", error_message="Invalid ab_test_control_setups", result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "ab_test_control_setups must be an array of objects when provided")

    if campaign_budget_optimization is not None and not isinstance(campaign_budget_optimization, bool):
        _log("failed", error_message="Invalid campaign_budget_optimization", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "campaign_budget_optimization must be a boolean when provided")

    # ---- resolve auth session ----
    sessions = _load("meta_auth_sessions.json")

    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp is not None and exp <= datetime.datetime.now(datetime.timezone.utc):
            return False
        if not s.get("access_token_ciphertext") and access_token is None:
            return False
        return True

    resolved = None
    if access_token is not None:
        tok = access_token.strip()
        for s in sessions:
            if isinstance(s, dict) and (s.get("id") == tok or (s.get("access_token_ciphertext") and s.get("access_token_ciphertext") == tok)):
                if _session_valid(s) or s.get("status") == "active":
                    resolved = s
                    break
        if resolved is None:
            valid = [s for s in sessions if _session_valid(s)]
            if valid:
                valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
                resolved = valid[0]
    else:
        valid = [s for s in sessions if _session_valid(s)]
        if valid:
            valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            resolved = valid[0]

    if resolved is None:
        _log("failed", error_message="No valid Meta auth session", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("UNAUTHORIZED", "No valid Meta access token available (no active auth session)")

    # ---- resolve account row ----
    accounts = _load("ad_accounts.json")
    acct = None
    if account_id is not None:
        aid = account_id.strip()
        for a in accounts:
            if isinstance(a, dict) and a.get("external_meta_account_id") == aid:
                acct = a
                break
        if acct is None:
            _log("failed", auth_session_id=resolved.get("id"), object_id=aid, error_message="Account not found",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "Ad account not found for the given account_id")
    else:
        cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("auth_session_id") == resolved.get("id")]
        if not cand:
            cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if cand:
            cand.sort(key=lambda r: (r.get("last_synced_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            acct = cand[0]
        if acct is None:
            _log("failed", auth_session_id=resolved.get("id"), error_message="No ad accounts available",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "No cached ad accounts available to create a campaign in")

    # ---- create row ----
    ad_objects = _load("ad_objects.json")
    now = _now_iso()

    # Meta campaign ids are numeric strings; generate a plausible unique one in-store
    existing_ids = {o.get("external_meta_id") for o in ad_objects if isinstance(o, dict) and o.get("object_type") == "campaign"}
    external_meta_id = None
    for _ in range(20):
        cand_id = str(int(time.time() * 1000)) + str(int(uuid.uuid4().int % 1000000)).rjust(6, "0")
        if cand_id not in existing_ids:
            external_meta_id = cand_id
            break
    if external_meta_id is None:
        _log("failed", auth_session_id=resolved.get("id"), account_row_id=acct.get("id"), error_message="Could not allocate campaign id",
             result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("CONFLICT", "Could not allocate a unique campaign id")

    new_id = "meta_obj_" + uuid.uuid4().hex
    row = {
        "id": new_id,
        "account_id": acct.get("id"),
        "object_type": "campaign",
        "external_meta_id": external_meta_id,
        "parent_campaign_external_id": None,
        "parent_adset_external_id": None,
        "name": (name.strip() if isinstance(name, str) and name.strip() else f"Campaign {external_meta_id}"),
        "objective": (objective.strip() if isinstance(objective, str) and objective.strip() else None),
        "buying_type": (buying_type.strip() if isinstance(buying_type, str) and buying_type.strip() else None),
        "bid_strategy": (bid_strategy.strip() if isinstance(bid_strategy, str) and bid_strategy.strip() else None),
        "bid_cap": (bid_cap.strip() if isinstance(bid_cap, str) and bid_cap is not None else None),
        "bid_amount_minor": None,
        "daily_budget_minor_str": (daily_budget.strip() if isinstance(daily_budget, str) and daily_budget is not None else None),
        "lifetime_budget_minor_str": (lifetime_budget.strip() if isinstance(lifetime_budget, str) and lifetime_budget is not None else None),
        "spend_cap_minor_str": (spend_cap.strip() if isinstance(spend_cap, str) and spend_cap is not None else None),
        "campaign_budget_optimization": campaign_budget_optimization,
        "special_ad_categories": special_ad_categories,
        "ab_test_control_setups": ab_test_control_setups,
        "targeting": None,
        "optimization_goal": None,
        "billing_event": None,
        "start_time": None,
        "end_time": None,
        "frequency_control_specs": None,
        "creative_external_id": None,
        "tracking_specs": None,
        "configured_status": status,
        "effective_status": None,
        "status": "active",
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now
    }

    # constraint checks
    if row["daily_budget_minor_str"] is not None and not re.match(r"^[0-9]+$", row["daily_budget_minor_str"]):
        _log("failed", auth_session_id=resolved.get("id"), account_row_id=acct.get("id"), error_message="Invalid daily_budget format")
        return _err("VALIDATION_ERROR", "daily_budget must be a string of digits in minor units")
    if row["lifetime_budget_minor_str"] is not None and not re.match(r"^[0-9]+$", row["lifetime_budget_minor_str"]):
        _log("failed", auth_session_id=resolved.get("id"), account_row_id=acct.get("id"), error_message="Invalid lifetime_budget format")
        return _err("VALIDATION_ERROR", "lifetime_budget must be a string of digits in minor units")
    if row["spend_cap_minor_str"] is not None and not re.match(r"^[0-9]+$", row["spend_cap_minor_str"]):
        _log("failed", auth_session_id=resolved.get("id"), account_row_id=acct.get("id"), error_message="Invalid spend_cap format")
        return _err("VALIDATION_ERROR", "spend_cap must be a string of digits in minor units")

    ad_objects.append(row)
    _save("ad_objects.json", ad_objects)

    # update session last_used_at
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == resolved.get("id"):
            s["last_used_at"] = now
            s["updated_at"] = now
            break
    _save("meta_auth_sessions.json", sessions)

    _log("succeeded", auth_session_id=resolved.get("id"), account_row_id=acct.get("id"), object_id=external_meta_id,
         result_payload={"created_object_id": external_meta_id, "latency_ms": int((time.time()-t0)*1000)})

    return {
        "id": external_meta_id,
        "campaign": row,
        "meta": {"resolved_auth_session_id": resolved.get("id"), "latency_ms": int((time.time()-t0)*1000)}
    }

