            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        rows.append(job)
        _save("analytics_and_archive.json", rows)
        return job

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        now = _now_dt()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("auth_session_id") != auth_session_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    # --- Validate inputs (relaxed per schema: campaign_id is optional param but required to have effect) ---
    if campaign_id is None or (isinstance(campaign_id, str) and campaign_id.strip() == ""):
        job = _append_audit("failed", object_id=campaign_id or None, error_message="campaign_id is required")
        job["updated_at"] = _now_iso()
        aa = _load("analytics_and_archive.json")
        for i in range(len(aa) - 1, -1, -1):
            if aa[i].get("id") == job["id"]:
                aa[i] = job
                break
        _save("analytics_and_archive.json", aa)
        return _err("VALIDATION_ERROR", "campaign_id is required", campaign_id=campaign_id)

    if not isinstance(campaign_id, str):
        _append_audit("failed", object_id=str(campaign_id), error_message="campaign_id must be a string")
        return _err("VALIDATION_ERROR", "campaign_id must be a string", campaign_id=campaign_id)

    # Determine if any update field provided: do NOT require any, accept no-op as validation? Real APIs usually reject.
    # Audit defect indicates their call had all nulls and was rejected; relax to accept and return current row (idempotent).
    update_fields_present = any(v is not None for v in [
        name, status, special_ad_categories, daily_budget, lifetime_budget,
        bid_strategy, bid_cap, spend_cap, campaign_budget_optimization, objective
    ])

    # Type validation for provided fields
    if name is not None and not isinstance(name, str):
        _append_audit("failed", object_id=campaign_id, error_message="name must be a string")
        return _err("VALIDATION_ERROR", "name must be a string")
    if status is not None and not isinstance(status, str):
        _append_audit("failed", object_id=campaign_id, error_message="status must be a string")
        return _err("VALIDATION_ERROR", "status must be a string")
    if special_ad_categories is not None:
        if not isinstance(special_ad_categories, list) or any(not isinstance(x, str) for x in special_ad_categories):
            _append_audit("failed", object_id=campaign_id, error_message="special_ad_categories must be an array of strings")
            return _err("VALIDATION_ERROR", "special_ad_categories must be an array of strings")
    for fld_name, fld_val in [("daily_budget", daily_budget), ("lifetime_budget", lifetime_budget), ("bid_cap", bid_cap), ("spend_cap", spend_cap)]:
        if fld_val is not None:
            if not isinstance(fld_val, str) or not re.fullmatch(r"[0-9]+", fld_val):
                _append_audit("failed", object_id=campaign_id, error_message=f"{fld_name} must be a numeric string in minor units")
                return _err("VALIDATION_ERROR", f"{fld_name} must be a numeric string in minor units")
    if bid_strategy is not None and not isinstance(bid_strategy, str):
        _append_audit("failed", object_id=campaign_id, error_message="bid_strategy must be a string")
        return _err("VALIDATION_ERROR", "bid_strategy must be a string")
    if campaign_budget_optimization is not None and not isinstance(campaign_budget_optimization, bool):
        _append_audit("failed", object_id=campaign_id, error_message="campaign_budget_optimization must be a boolean")
        return _err("VALIDATION_ERROR", "campaign_budget_optimization must be a boolean")
    if objective is not None and not isinstance(objective, str):
        _append_audit("failed", object_id=campaign_id, error_message="objective must be a string")
        return _err("VALIDATION_ERROR", "objective must be a string")

    # --- Resolve auth session context ---
    auth_rows = _load("meta_auth_sessions.json")
    now_dt = _now_dt()

    def _is_session_usable(s):
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp and exp <= now_dt:
            return False
        return True

    auth_session = None
    if access_token is not None:
        if not isinstance(access_token, str):
            _append_audit("failed", object_id=campaign_id, error_message="access_token must be a string")
            return _err("VALIDATION_ERROR", "access_token must be a string")
        # Authenticate by matching visible value OR id (never compare to ciphertext)
        for s in auth_rows:
            if not _is_session_usable(s):
                continue
            if access_token == s.get("id") or access_token == s.get("access_token_ciphertext"):
                auth_session = s
                break
        if auth_session is None:
            # still allow provided token without cached session: accept (caller is authenticated externally)
            auth_session = {"id": None}
    else:
        # Ambient auth: pick any usable active session in store (must exist)
        for s in auth_rows:
            if _is_session_usable(s):
                auth_session = s
                break
        if auth_session is None:
            _append_audit("failed", object_id=campaign_id, error_message="No active Meta auth session available")
            return _err("UNAUTHORIZED", "No active Meta auth session available")

    ok, rl_err = _rate_limit_check(auth_session.get("id"))
    if not ok:
        _append_audit("failed", auth_session_id=auth_session.get("id"), object_id=campaign_id, error_message=rl_err["error"]["message"])
        return rl_err

    # --- Find campaign row by external_meta_id and object_type ---
    objs = _load("ad_objects.json")
    camp = None
    for r in objs:
        if r.get("object_type") == "campaign" and r.get("external_meta_id") == campaign_id:
            camp = r
            break
    if camp is None:
        _append_audit("failed", auth_session_id=auth_session.get("id"), object_id=campaign_id, error_message="Campaign not found")
        return _err("NOT_FOUND", "Campaign not found", campaign_id=campaign_id)

    # If no fields provided, behave idempotently: update last_used_at/audit and return current.
    if not update_fields_present:
        # touch auth session last_used_at if it is a stored session
        if auth_session.get("id"):
            for s in auth_rows:
                if s.get("id") == auth_session["id"]:
                    s["last_used_at"] = _now_iso()
                    s["updated_at"] = _now_iso()
                    break
            _save("meta_auth_sessions.json", auth_rows)

        payload = {"campaign": camp, "updated": False}
        _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=camp.get("account_id"), object_id=campaign_id, payload=payload)
        return payload

    # Enforce configured_status transition rules (lifecycle)
    if status is not None:
        allowed_statuses = {"ACTIVE", "PAUSED", "DELETED", "ARCHIVED"}
        if status not in allowed_statuses:
            _append_audit("failed", auth_session_id=auth_session.get("id"), account_row_id=camp.get("account_id"), object_id=campaign_id, error_message="Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_statuses)))
        current = camp.get("configured_status")
        transitions = {
            "PAUSED": {"ACTIVE", "ARCHIVED", "DELETED"},
            "ACTIVE": {"PAUSED", "ARCHIVED", "DELETED"},
            "ARCHIVED": {"PAUSED", "DELETED"},
            "DELETED": set()
        }
        if current in transitions and status != current and status not in transitions[current]:
            _append_audit("failed", auth_session_id=auth_session.get("id"), account_row_id=camp.get("account_id"), object_id=campaign_id, error_message="Invalid status transition")
            return _err("INVALID_TRANSITION", f"Invalid configured_status transition from {current} to {status}", from_status=current, to_status=status)

    # Apply only provided fields
    changed = False
    if name is not None and name != camp.get("name"):
        camp["name"] = name
        changed = True
    if objective is not None and objective != camp.get("objective"):
        camp["objective"] = objective
        changed = True
    if bid_strategy is not None and bid_strategy != camp.get("bid_strategy"):
        camp["bid_strategy"] = bid_strategy
        changed = True
    if bid_cap is not None and bid_cap != camp.get("bid_cap"):
        camp["bid_cap"] = bid_cap
        changed = True
    if spend_cap is not None and spend_cap != camp.get("spend_cap_minor_str"):
        camp["spend_cap_minor_str"] = spend_cap
        changed = True
    if daily_budget is not None and daily_budget != camp.get("daily_budget_minor_str"):
        camp["daily_budget_minor_str"] = daily_budget
        changed = True
    if lifetime_budget is not None and lifetime_budget != camp.get("lifetime_budget_minor_str"):
        camp["lifetime_budget_minor_str"] = lifetime_budget
        changed = True
    if special_ad_categories is not None and special_ad_categories != camp.get("special_ad_categories"):
        camp["special_ad_categories"] = special_ad_categories
        changed = True
    if campaign_budget_optimization is not None and campaign_budget_optimization != camp.get("campaign_budget_optimization"):
        camp["campaign_budget_optimization"] = campaign_budget_optimization
        changed = True
    if status is not None and status != camp.get("configured_status"):
        camp["configured_status"] = status
        changed = True

    if not changed:
        # still touch timestamps (Meta would likely ack no change). But "no success without effect" applies to mutations
        # that matched no row; we matched a row. We'll return updated=False.
        if auth_session.get("id"):
            for s in auth_rows:
                if s.get("id") == auth_session["id"]:
                    s["last_used_at"] = _now_iso()
                    s["updated_at"] = _now_iso()
                    break
            _save("meta_auth_sessions.json", auth_rows)

        payload = {"campaign": camp, "updated": False}
        _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=camp.get("account_id"), object_id=campaign_id, payload=payload)
        return payload

    camp["updated_at"] = _now_iso()
    # Persist updated row
    for i in range(len(objs)):
        if objs[i].get("id") == camp.get("id"):
            objs[i] = camp
            break
    _save("ad_objects.json", objs)

    # Touch auth session usage
    if auth_session.get("id"):
        for s in auth_rows:
            if s.get("id") == auth_session["id"]:
                s["last_used_at"] = _now_iso()
                s["updated_at"] = _now_iso()
                break
        _save("meta_auth_sessions.json", auth_rows)

    payload = {"campaign": camp, "updated": True, "latency_ms": int((time.time() - t0) * 1000)}
    _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=camp.get("account_id"), object_id=campaign_id, payload=payload)
    return payload

def get_adsets(access_token=None, account_id=None, limit=10, campaign_id="", **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_adsets"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, error_message=None, payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "adset",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": limit if isinstance(limit, int) else None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    # validation (account_id optional; campaign_id optional string)
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")
    if account_id is not None:
        if not isinstance(account_id, str):
            _append_audit("failed", error_message="account_id must be a string or null", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be a string or null")
        account_id = account_id.strip()
        if account_id == "":
            account_id = None
    if not isinstance(limit, int):
        _append_audit("failed", error_message="limit must be an integer", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        _append_audit("failed", error_message="limit must be between 1 and 500", payload={"latency_ms": int((time.time()-t0)*1000), "limit": limit})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
    if campaign_id is None:
        campaign_id = ""
    if not isinstance(campaign_id, str):
        _append_audit("failed", error_message="campaign_id must be a string", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "campaign_id must be a string")
    campaign_id = campaign_id.strip()

    # auth
    sessions = _load("meta_auth_sessions.json")

    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        if not s.get("access_token_ciphertext"):
            return False
        exp = _parse_dt_any(s.get("token_expires_at"))
        if exp is not None and exp <= _now_dt():
            return False
        return True

    resolved = None
    token_mode = "cached"
    if access_token is not None and access_token.strip():
        token_mode = "provided"
        for s in sessions:
            if s.get("id") == access_token or s.get("access_token_ciphertext") == access_token:
                if _session_valid(s):
                    resolved = s
                    break
        if resolved is None:
            for s in sessions:
                if _session_valid(s):
                    resolved = s
                    break
            if resolved is None:
                _append_audit("failed", error_message="No valid auth session available", payload={"latency_ms": int((time.time()-t0)*1000)})
                return _err("UNAUTHORIZED", "No valid cached Meta auth session available")
    else:
        candidates = [s for s in sessions if _session_valid(s)]
        candidates.sort(key=lambda r: (r.get("last_used_at") or "", r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        resolved = candidates[0] if candidates else None
        if resolved is None:
            _append_audit("failed", error_message="No valid auth session available", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    # rate limit
    aa = _load("analytics_and_archive.json")
    window_s = 60
    limit_per_window = 60
    cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in aa:
        if r.get("auth_session_id") != resolved.get("id"):
            continue
        dt = _parse_dt_any(r.get("created_at"))
        if dt is not None and dt >= cutoff:
            recent += 1
    if recent >= limit_per_window:
        _append_audit("failed", auth_session_id=resolved.get("id"), error_message="Rate limit exceeded", payload={"recent": recent, "window_s": window_s, "latency_ms": int((time.time()-t0)*1000)})
        return _err("RATE_LIMIT", "Too many requests; please retry later", window_s=window_s, limit=limit_per_window)

    # resolve account row
    accounts = _load("ad_accounts.json")
    account_row = None
    if account_id is not None:
        for a in accounts:
            if a.get("external_meta_account_id") == account_id or a.get("id") == account_id:
                account_row = a
                break
        if account_row is None:
            _append_audit("succeeded", auth_session_id=resolved.get("id"), payload={"data": [], "total": 0, "has_more": False, "latency_ms": int((time.time()-t0)*1000)})
            return {"data": [], "total": 0, "has_more": False, "next_cursor": None}
    else:
        by_session = [a for a in accounts if a.get("auth_session_id") == resolved.get("id")]
        if by_session:
            account_row = by_session[0]
        else:
            active = [a for a in accounts if a.get("status") == "active"]
            account_row = active[0] if active else (accounts[0] if accounts else None)
        if account_row is None:
            _append_audit("failed", auth_session_id=resolved.get("id"), error_message="No ad account available", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "No ad account is available in the local datastore for this auth context")

    # filter adsets
    objs = _load("ad_objects.json")
    adsets = [o for o in objs if o.get("account_id") == account_row.get("id") and o.get("object_type") == "adset" and o.get("status") != "deleted"]
    if campaign_id:
        adsets = [o for o in adsets if o.get("parent_campaign_external_id") == campaign_id]

    adsets.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)

    total = len(adsets)
    out = adsets[:limit]
    has_more = total > limit

    # update session last_used_at
    now_iso = _now_iso()
    for s in sessions:
        if s.get("id") == resolved.get("id"):
            s["last_used_at"] = now_iso
            s["updated_at"] = now_iso
            break
    _save("meta_auth_sessions.json", sessions)

    _append_audit("succeeded", auth_session_id=resolved.get("id"), account_row_id=account_row.get("id"),
                  payload={"total": total, "returned": len(out), "has_more": has_more, "latency_ms": int((time.time()-t0)*1000)})
    return {"data": out, "total": total, "has_more": has_more, "next_cursor": None}

