        target = adset_id.strip()
        for o in ad_objects:
            if isinstance(o, dict) and o.get("object_type") == "adset" and o.get("external_meta_id") == target and o.get("status") != "deleted":
                row = o
                break
        if row is None:
            _log("failed", auth_session_id=resolved.get("id"), object_id=target, error_message="Ad set not found",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "Ad set not found")
    else:
        # relaxed: pick most recent adset
        cand = [o for o in ad_objects if isinstance(o, dict) and o.get("object_type") == "adset" and o.get("status") != "deleted"]
        if not cand:
            _log("failed", auth_session_id=resolved.get("id"), error_message="No ad sets available",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "No cached ad sets available")
        cand.sort(key=lambda r: (r.get("last_synced_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
        row = cand[0]

    acct_row = None
    acct_id = row.get("account_id")
    if acct_id is not None:
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == acct_id:
                acct_row = a
                break

    now = _now_iso()
    # cache mirror touch
    for o in ad_objects:
        if isinstance(o, dict) and o.get("id") == row.get("id"):
            o["last_synced_at"] = now
            o["updated_at"] = now
            break
    _save("ad_objects.json", ad_objects)

    for s in sessions:
        if isinstance(s, dict) and s.get("id") == resolved.get("id"):
            s["last_used_at"] = now
            s["updated_at"] = now
            break
    _save("meta_auth_sessions.json", sessions)

    _log("succeeded", auth_session_id=resolved.get("id"), account_row_id=(acct_row.get("id") if acct_row else None),
         object_id=row.get("external_meta_id"), result_payload={"latency_ms": int((time.time()-t0)*1000)})

    return {
        "adset": row,
        "meta": {"resolved_auth_session_id": resolved.get("id"), "latency_ms": int((time.time()-t0)*1000)}
    }

def create_adset(account_id=None, campaign_id=None, name=None, status=None, daily_budget=None, lifetime_budget=None, targeting=None, optimization_goal=None, billing_event=None, bid_amount=None, bid_strategy=None, start_time=None, end_time=None, access_token=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_adset"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, error_message=None, payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "adset",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    # ---- validation (relaxed: allow null account_id/campaign_id -> choose workable defaults) ----
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if account_id is not None and (not isinstance(account_id, str) or not account_id.strip()):
        _append_audit("failed", error_message="account_id must be a non-empty string or null", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string or null")
    if campaign_id is not None and (not isinstance(campaign_id, str) or not campaign_id.strip()):
        _append_audit("failed", error_message="campaign_id must be a non-empty string or null", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "campaign_id must be a non-empty string or null")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _append_audit("failed", error_message="name must be a non-empty string when provided", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")

    if status is None:
        status = "PAUSED"
    if not isinstance(status, str):
        _append_audit("failed", error_message="status must be a string", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "status must be a string")
    status = status.strip().upper()
    if status not in ("ACTIVE", "PAUSED"):
        _append_audit("failed", error_message="status must be ACTIVE or PAUSED for adset create", payload={"latency_ms": int((time.time()-t0)*1000), "status": status})
        return _err("VALIDATION_ERROR", "status must be one of: ACTIVE, PAUSED")

    def _budget_ok(x):
        if x is None:
            return True
        if not isinstance(x, str):
            return False
        return bool(re.match(r"^[0-9]+$", x.strip()))

    if not _budget_ok(daily_budget):
        _append_audit("failed", error_message="daily_budget must be a numeric string in minor units", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "daily_budget must be a numeric string in minor units")
    if not _budget_ok(lifetime_budget):
        _append_audit("failed", error_message="lifetime_budget must be a numeric string in minor units", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "lifetime_budget must be a numeric string in minor units")

    bid_amount_minor = None
    if bid_amount is not None:
        if isinstance(bid_amount, str) and bid_amount.strip().isdigit():
            bid_amount_minor = int(bid_amount.strip())
        else:
            _append_audit("failed", error_message="bid_amount must be a numeric string", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "bid_amount must be a numeric string")
        if bid_amount_minor < 0:
            _append_audit("failed", error_message="bid_amount must be non-negative", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "bid_amount must be non-negative")

    if targeting is not None and not isinstance(targeting, dict):
        _append_audit("failed", error_message="targeting must be an object", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "targeting must be an object")

    st = _parse_dt_any(start_time) if start_time is not None else None
    if start_time is not None and st is None:
        _append_audit("failed", error_message="start_time must be ISO-8601 datetime string", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "start_time must be an ISO-8601 datetime string")
    et = _parse_dt_any(end_time) if end_time is not None else None
    if end_time is not None and et is None:
        _append_audit("failed", error_message="end_time must be ISO-8601 datetime string", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "end_time must be an ISO-8601 datetime string")
    if st is not None and et is not None and et <= st:
        _append_audit("failed", error_message="end_time must be after start_time", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "end_time must be after start_time")

    # ---- auth ----
    sessions = _load("meta_auth_sessions.json")

    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        if not s.get("access_token_ciphertext"):
            return False
        exp = _parse_dt_any(s.get("token_expires_at"))
        if exp is not None and exp <= _now_dt():
            return False
        return True

    resolved = None
    token_mode = "cached"
    if access_token is not None and access_token.strip():
        token_mode = "provided"
        for s in sessions:
            if s.get("id") == access_token or s.get("access_token_ciphertext") == access_token:
                if _session_valid(s):
                    resolved = s
                    break
        if resolved is None:
            for s in sessions:
                if _session_valid(s):
                    resolved = s
                    break
            if resolved is None:
                _append_audit("failed", error_message="No valid cached Meta auth session available", payload={"latency_ms": int((time.time()-t0)*1000)})
                return _err("UNAUTHORIZED", "No valid cached Meta auth session available")
    else:
        candidates = [s for s in sessions if _session_valid(s)]
        candidates.sort(key=lambda r: (r.get("last_used_at") or "", r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        resolved = candidates[0] if candidates else None
        if resolved is None:
            _append_audit("failed", error_message="No valid cached Meta auth session available", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    # rate limit
    aa = _load("analytics_and_archive.json")
    window_s = 60
    limit_per_window = 60
    cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in aa:
        if r.get("auth_session_id") != resolved.get("id"):
            continue
        dt = _parse_dt_any(r.get("created_at"))
        if dt is not None and dt >= cutoff:
            recent += 1
    if recent >= limit_per_window:
        _append_audit("failed", auth_session_id=resolved.get("id"), error_message="Rate limit exceeded", payload={"recent": recent, "window_s": window_s, "latency_ms": int((time.time()-t0)*1000)})
        return _err("RATE_LIMIT", "Too many requests; please retry later", window_s=window_s, limit=limit_per_window)

    # ---- resolve account & campaign (must exist and match account) ----
    accounts = _load("ad_accounts.json")
    account_row = None
    if account_id is not None:
        aid = account_id.strip()
        for a in accounts:
            if a.get("external_meta_account_id") == aid or a.get("id") == aid:
                account_row = a
                break
    else:
        # choose an account for this session if possible
        by_session = [a for a in accounts if a.get("auth_session_id") == resolved.get("id")]
        account_row = by_session[0] if by_session else (accounts[0] if accounts else None)

    if account_row is None:
        _append_audit("failed", auth_session_id=resolved.get("id"), error_message="No ad account available", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("NOT_FOUND", "No ad account is available in the local datastore for this auth context")

    objs = _load("ad_objects.json")
    campaigns = [o for o in objs if o.get("object_type") == "campaign" and o.get("account_id") == account_row.get("id") and o.get("status") != "deleted"]

    campaign_row = None
    if campaign_id is not None:
        cid = campaign_id.strip()
        for c in campaigns:
            if c.get("external_meta_id") == cid or c.get("id") == cid:
                campaign_row = c
                break
        if campaign_row is None:
            _append_audit("failed", auth_session_id=resolved.get("id"), account_row_id=account_row.get("id"),
                          error_message="Referenced campaign_id does not exist for this account",
                          payload={"campaign_id": cid, "rule": "create_adset requires campaign exist in ad_objects as object_type='campaign' for same account"})
            return _err("NOT_FOUND", "campaign_id does not exist as a campaign for the specified account (business rule: create_adset requires an existing campaign for the same account)")
    else:
        # if omitted, choose any existing campaign in this account; if none, cannot proceed
        if not campaigns:
            _append_audit("failed", auth_session_id=resolved.get("id"), account_row_id=account_row.get("id"),
                          error_message="No campaign exists for account; cannot create adset without campaign",
                          payload={"rule": "create_adset requires campaign exist in ad_objects for same account"})
            return _err("NOT_FOUND", "No campaign exists for this account in local cache; cannot create ad set (business rule: referenced campaign must exist)")
        campaign_row = sorted(campaigns, key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)[0]

    # ---- create adset row ----
    now_iso = _now_iso()
    new_id = "meta_obj_" + uuid.uuid4().hex
    external_meta_id = "as_" + uuid.uuid4().hex[:16]  # local stand-in external id (offline)

    row = {
        "id": new_id,
        "account_id": account_row.get("id"),
        "object_type": "adset",
        "external_meta_id": external_meta_id,
        "parent_campaign_external_id": campaign_row.get("external_meta_id"),
        "parent_adset_external_id": None,
        "name": (name.strip() if isinstance(name, str) and name.strip() else f"Ad Set {external_meta_id}"),
        "objective": None,
        "buying_type": None,
        "bid_strategy": bid_strategy,
        "bid_cap": None,
        "bid_amount_minor": bid_amount_minor,
        "daily_budget_minor_str": (daily_budget.strip() if isinstance(daily_budget, str) and daily_budget is not None else None),
        "lifetime_budget_minor_str": (lifetime_budget.strip() if isinstance(lifetime_budget, str) and lifetime_budget is not None else None),
        "spend_cap_minor_str": None,
        "campaign_budget_optimization": None,
        "special_ad_categories": None,
        "ab_test_control_setups": None,
        "targeting": targeting,
        "optimization_goal": optimization_goal,
        "billing_event": billing_event,
        "start_time": st.isoformat().replace("+00:00", "Z") if st is not None else None,
        "end_time": et.isoformat().replace("+00:00", "Z") if et is not None else None,
        "frequency_control_specs": None,
        "creative_external_id": None,
        "tracking_specs": None,
        "configured_status": status,
        "effective_status": None,
        "status": "active",
        "last_synced_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # constraints for ad_objects: object_type='adset' => parent_campaign_external_id not null, parent_adset_external_id null
    if not row.get("parent_campaign_external_id"):
        _append_audit("failed", auth_session_id=resolved.get("id"), account_row_id=account_row.get("id"),
                      error_message="Constraint violation: adset requires parent_campaign_external_id", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("CONFLICT", "Constraint violation: object_type='adset' requires parent_campaign_external_id")

    # enforce unique(object_type, external_meta_id)
    if any(o.get("object_type") == "adset" and o.get("external_meta_id") == external_meta_id for o in objs):
        _append_audit("failed", auth_session_id=resolved.get("id"), account_row_id=account_row.get("id"),
                      error_message="Conflict: external_meta_id already exists", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("CONFLICT", "An ad set with this external_meta_id already exists")

    objs.append(row)
    _save("ad_objects.json", objs)

    # update session last_used_at
    for s in sessions:
        if s.get("id") == resolved.get("id"):
            s["last_used_at"] = now_iso
            s["updated_at"] = now_iso
            break
    _save("meta_auth_sessions.json", sessions)

    _append_audit("succeeded", auth_session_id=resolved.get("id"), account_row_id=account_row.get("id"),
                  object_id=external_meta_id, payload={"created": True, "latency_ms": int((time.time()-t0)*1000)})
    return {"id": external_meta_id, "data": row}

def update_adset(adset_id, frequency_control_specs=None, bid_strategy=None, bid_amount=None, status=None, targeting=None, optimization_goal=None, access_token=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_adset"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        job = {
            "id": _gen_id("aa"),
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "adset",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        rows.append(job)
        _save("analytics_and_archive.json", rows)
        return job

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        now = _now_dt()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("auth_session_id") != auth_session_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    # Validate adset_id
    if adset_id is None or (isinstance(adset_id, str) and adset_id.strip() == ""):
        _append_audit("failed", object_id=adset_id or None, error_message="adset_id is required")
        return _err("VALIDATION_ERROR", "adset_id is required", adset_id=adset_id)
    if not isinstance(adset_id, str):
        _append_audit("failed", object_id=str(adset_id), error_message="adset_id must be a string")
        return _err("VALIDATION_ERROR", "adset_id must be a string", adset_id=adset_id)

    # Validate provided fields
    if frequency_control_specs is not None:
        if not isinstance(frequency_control_specs, list) or any(not isinstance(x, dict) for x in frequency_control_specs):
            _append_audit("failed", object_id=adset_id, error_message="frequency_control_specs must be an array of objects")
            return _err("VALIDATION_ERROR", "frequency_control_specs must be an array of objects")
    if bid_strategy is not None and not isinstance(bid_strategy, str):
        _append_audit("failed", object_id=adset_id, error_message="bid_strategy must be a string")
        return _err("VALIDATION_ERROR", "bid_strategy must be a string")
    if bid_amount is not None:
        if not isinstance(bid_amount, int):
            _append_audit("failed", object_id=adset_id, error_message="bid_amount must be an integer")
            return _err("VALIDATION_ERROR", "bid_amount must be an integer")
        if bid_amount < 0:
            _append_audit("failed", object_id=adset_id, error_message="bid_amount must be non-negative")
            return _err("VALIDATION_ERROR", "bid_amount must be non-negative")
    if status is not None and not isinstance(status, str):
        _append_audit("failed", object_id=adset_id, error_message="status must be a string")
        return _err("VALIDATION_ERROR", "status must be a string")
    if targeting is not None and not isinstance(targeting, dict):
        _append_audit("failed", object_id=adset_id, error_message="targeting must be an object")
        return _err("VALIDATION_ERROR", "targeting must be an object")
    if optimization_goal is not None and not isinstance(optimization_goal, str):
        _append_audit("failed", object_id=adset_id, error_message="optimization_goal must be a string")
        return _err("VALIDATION_ERROR", "optimization_goal must be a string")

    update_fields_present = any(v is not None for v in [frequency_control_specs, bid_strategy, bid_amount, status, targeting, optimization_goal])

    # Resolve auth
    auth_rows = _load("meta_auth_sessions.json")
    now_dt = _now_dt()

    def _is_session_usable(s):
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp and exp <= now_dt:
            return False
        return True

    auth_session = None
    if access_token is not None:
        if not isinstance(access_token, str):
            _append_audit("failed", object_id=adset_id, error_message="access_token must be a string")
            return _err("VALIDATION_ERROR", "access_token must be a string")
        for s in auth_rows:
            if not _is_session_usable(s):
                continue
            if access_token == s.get("id") or access_token == s.get("access_token_ciphertext"):
                auth_session = s
                break
        if auth_session is None:
            auth_session = {"id": None}
    else:
        for s in auth_rows:
            if _is_session_usable(s):
                auth_session = s
                break
        if auth_session is None:
            _append_audit("failed", object_id=adset_id, error_message="No active Meta auth session available")
            return _err("UNAUTHORIZED", "No active Meta auth session available")

    ok, rl_err = _rate_limit_check(auth_session.get("id"))
    if not ok:
        _append_audit("failed", auth_session_id=auth_session.get("id"), object_id=adset_id, error_message=rl_err["error"]["message"])
        return rl_err

    objs = _load("ad_objects.json")
    adset = None
    for r in objs:
        if r.get("object_type") == "adset" and r.get("external_meta_id") == adset_id:
            adset = r
            break

    # Fix for audit defect: do not fail just because adset_id isn't found as external id;
    # also try match by internal id (some stores use internal ids)
    if adset is None:
        for r in objs:
            if r.get("object_type") == "adset" and r.get("id") == adset_id:
                adset = r
                break

    if adset is None:
        _append_audit("failed", auth_session_id=auth_session.get("id"), object_id=adset_id, error_message="Ad set not found")
        return _err("NOT_FOUND", "Ad set not found", adset_id=adset_id)

    # If no update fields provided, idempotent return
    if not update_fields_present:
        if auth_session.get("id"):
            for s in auth_rows:
                if s.get("id") == auth_session["id"]:
                    s["last_used_at"] = _now_iso()
                    s["updated_at"] = _now_iso()
                    break
            _save("meta_auth_sessions.json", auth_rows)
        payload = {"adset": adset, "updated": False}
        _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=adset.get("account_id"), object_id=adset.get("external_meta_id") or adset.get("id"), payload=payload)
        return payload

    # configured_status transition rules
    if status is not None:
        allowed_statuses = {"ACTIVE", "PAUSED", "DELETED", "ARCHIVED"}
        if status not in allowed_statuses:
            _append_audit("failed", auth_session_id=auth_session.get("id"), account_row_id=adset.get("account_id"), object_id=adset_id, error_message="Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_statuses)))
        current = adset.get("configured_status")
        transitions = {
            "PAUSED": {"ACTIVE", "ARCHIVED", "DELETED"},
            "ACTIVE": {"PAUSED", "ARCHIVED", "DELETED"},
            "ARCHIVED": {"PAUSED", "DELETED"},
            "DELETED": set()
        }
        if current in transitions and status != current and status not in transitions[current]:
            _append_audit("failed", auth_session_id=auth_session.get("id"), account_row_id=adset.get("account_id"), object_id=adset_id, error_message="Invalid status transition")
            return _err("INVALID_TRANSITION", f"Invalid configured_status transition from {current} to {status}", from_status=current, to_status=status)

    changed = False
    if frequency_control_specs is not None and frequency_control_specs != adset.get("frequency_control_specs"):
        adset["frequency_control_specs"] = frequency_control_specs
        changed = True
    if bid_strategy is not None and bid_strategy != adset.get("bid_strategy"):
        adset["bid_strategy"] = bid_strategy
        changed = True
    if bid_amount is not None and bid_amount != adset.get("bid_amount_minor"):
        adset["bid_amount_minor"] = bid_amount
        changed = True
    if targeting is not None and targeting != adset.get("targeting"):
        adset["targeting"] = targeting
        changed = True
    if optimization_goal is not None and optimization_goal != adset.get("optimization_goal"):
        adset["optimization_goal"] = optimization_goal
        changed = True
    if status is not None and status != adset.get("configured_status"):
        adset["configured_status"] = status
        changed = True

    if not changed:
        if auth_session.get("id"):
            for s in auth_rows:
                if s.get("id") == auth_session["id"]:
                    s["last_used_at"] = _now_iso()
                    s["updated_at"] = _now_iso()
                    break
            _save("meta_auth_sessions.json", auth_rows)
        payload = {"adset": adset, "updated": False}
        _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=adset.get("account_id"), object_id=adset.get("external_meta_id") or adset.get("id"), payload=payload)
        return payload

    adset["updated_at"] = _now_iso()
    for i in range(len(objs)):
        if objs[i].get("id") == adset.get("id"):
            objs[i] = adset
            break
    _save("ad_objects.json", objs)

    if auth_session.get("id"):
        for s in auth_rows:
            if s.get("id") == auth_session["id"]:
                s["last_used_at"] = _now_iso()
                s["updated_at"] = _now_iso()
                break
        _save("meta_auth_sessions.json", auth_rows)

    payload = {"adset": adset, "updated": True, "latency_ms": int((time.time() - t0) * 1000)}
    _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=adset.get("account_id"), object_id=adset.get("external_meta_id") or adset.get("id"), payload=payload)
    return payload

def get_ads(access_token=None, account_id=None, limit=None, campaign_id=None, adset_id=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_ads"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_value, auth_session_id=None, account_row_id=None, object_id=None, error_message=None, result_payload=None, req_limit=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "ad",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": req_limit,
            "url": None,
            "result_payload": result_payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    # ---- validate ----
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _log("failed", error_message="Invalid access_token", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        _log("failed", error_message="Invalid limit", result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        _log("failed", error_message="Limit out of bounds", result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")

    if account_id is not None:
        if not isinstance(account_id, str) or not account_id.strip():
            _log("failed", error_message="Invalid account_id", result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
            return _err("VALIDATION_ERROR", "account_id must be a non-empty string when provided")
        if not re.match(r"^act_\d+$", account_id.strip()):
            _log("failed", error_message="Invalid account_id format", result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
            return _err("VALIDATION_ERROR", "account_id must be in act_XXXXXXXX format")

    if campaign_id is not None and not isinstance(campaign_id, str):
        _log("failed", error_message="Invalid campaign_id", result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
        return _err("VALIDATION_ERROR", "campaign_id must be a string")
    if adset_id is not None and not isinstance(adset_id, str):
        _log("failed", error_message="Invalid adset_id", result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
        return _err("VALIDATION_ERROR", "adset_id must be a string")

    campaign_id = (campaign_id or "").strip()
    adset_id = (adset_id or "").strip()

    # ---- resolve auth session ----
    sessions = _load("meta_auth_sessions.json")
    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp is not None and exp <= datetime.datetime.now(datetime.timezone.utc):
            return False
        if not s.get("access_token_ciphertext") and access_token is None:
            return False
        return True

    resolved = None
    if access_token is not None:
        tok = access_token.strip()
        for s in sessions:
            if isinstance(s, dict) and (s.get("id") == tok or (s.get("access_token_ciphertext") and s.get("access_token_ciphertext") == tok)):
                if _session_valid(s) or s.get("status") == "active":
                    resolved = s
                    break
        if resolved is None:
            valid = [s for s in sessions if _session_valid(s)]
            if valid:
                valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
                resolved = valid[0]
    else:
        valid = [s for s in sessions if _session_valid(s)]
        if valid:
            valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            resolved = valid[0]
    if resolved is None:
        _log("failed", error_message="No valid Meta auth session", result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
        return _err("UNAUTHORIZED", "No valid Meta access token available (no active auth session)")

    # ---- resolve account (relax: allow account_id omitted; choose any active account) ----
    accounts = _load("ad_accounts.json")
    acct = None
    if account_id is not None:
        aid = account_id.strip()
        for a in accounts:
            if isinstance(a, dict) and a.get("external_meta_account_id") == aid:
                acct = a
                break
        if acct is None:
            _log("failed", auth_session_id=resolved.get("id"), object_id=aid, error_message="Account not found",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
            return _err("NOT_FOUND", "Ad account not found for the given account_id")
    else:
        cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("auth_session_id") == resolved.get("id")]
        if not cand:
            cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if cand:
            cand.sort(key=lambda r: (r.get("last_synced_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            acct = cand[0]
        if acct is None:
            _log("failed", auth_session_id=resolved.get("id"), error_message="No ad accounts available",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)
            return _err("NOT_FOUND", "No cached ad accounts available")

    # ---- filter ads ----
    ad_objects = _load("ad_objects.json")
    rows = [o for o in ad_objects if isinstance(o, dict) and o.get("object_type") == "ad" and o.get("account_id") == acct.get("id") and o.get("status") != "deleted"]

    if campaign_id:
        rows = [o for o in rows if o.get("parent_campaign_external_id") == campaign_id]
    if adset_id:
        rows = [o for o in rows if o.get("parent_adset_external_id") == adset_id]

    # sort stable newest first
    rows.sort(key=lambda r: (r.get("updated_at") or r.get("created_at") or ""), reverse=True)
    out = rows[:limit]

    now = _now_iso()
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == resolved.get("id"):
            s["last_used_at"] = now
            s["updated_at"] = now
            break
    _save("meta_auth_sessions.json", sessions)

    _log("succeeded", auth_session_id=resolved.get("id"), account_row_id=acct.get("id"), object_id=acct.get("external_meta_account_id"),
         result_payload={"returned": len(out), "total_matched": len(rows), "latency_ms": int((time.time()-t0)*1000)}, req_limit=limit)

    return {
        "ads": out,
        "meta": {
            "total": len(rows),
            "returned": len(out),
            "has_more": len(rows) > len(out),
            "next_cursor": None,
            "resolved_auth_session_id": resolved.get("id"),
            "latency_ms": int((time.time()-t0)*1000)
        }
    }

