def create_ad(account_id=None, name=None, adset_id=None, creative_id=None, status=None, bid_amount=None, tracking_specs=None, access_token=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_ad"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "ad",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        window_s = 60
        limit_per_window = 60
        cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("job_type") not in ("insights_query", "ads_archive_search", "image_download_debug"):
                continue
            if (r.get("auth_session_id") or None) != (auth_session_id or None):
                continue
            ts = _parse_dt_any(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_s, limit=limit_per_window)
        return None

    def _resolve_session(token_param):
        sessions = _load("meta_auth_sessions.json")

        def _valid(s):
            if not isinstance(s, dict):
                return False
            if s.get("status") != "active":
                return False
            exp = _parse_dt_any(s.get("token_expires_at"))
            if exp is not None and exp <= _now_dt():
                return False
            if not s.get("access_token_ciphertext"):
                return False
            return True

        if token_param is not None:
            if not isinstance(token_param, str) or not token_param.strip():
                return None
            tok = token_param.strip()
            for s in sessions:
                if (s.get("id") == tok or s.get("access_token_ciphertext") == tok) and _valid(s):
                    return s
            return None

        for s in sessions:
            if _valid(s):
                return s
        return None

    # Validate inputs (schema allows nulls; must still ensure we can perform a real creation)
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if status is None:
        status = "PAUSED"
    if not isinstance(status, str) or not status.strip():
        _append_audit("failed", error_message="Invalid status", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "status must be a non-empty string")
    status = status.strip()
    if status not in ("ACTIVE", "PAUSED", "DELETED", "ARCHIVED"):
        _append_audit("failed", error_message="Unknown status enum", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "status must be one of ACTIVE, PAUSED, ARCHIVED, DELETED")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _append_audit("failed", error_message="name must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")

    if bid_amount is not None:
        if not isinstance(bid_amount, str) or not bid_amount.strip() or not re.match(r"^[0-9]+$", bid_amount.strip()):
            _append_audit("failed", error_message="bid_amount must be a string of digits when provided", payload={"endpoint": endpoint})
            return _err("VALIDATION_ERROR", "bid_amount must be a string of digits when provided")

    if tracking_specs is not None:
        if not isinstance(tracking_specs, list) or any(not isinstance(x, dict) for x in tracking_specs):
            _append_audit("failed", error_message="tracking_specs must be an array of objects when provided", payload={"endpoint": endpoint})
            return _err("VALIDATION_ERROR", "tracking_specs must be an array of objects when provided")

    session = _resolve_session(access_token)
    if session is None:
        _append_audit("failed", error_message="No valid cached Meta auth session available", payload={"endpoint": endpoint})
        return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    rl = _rate_limit_check(session.get("id"))
    if rl:
        _append_audit("failed", auth_session_id=session.get("id"), error_message=rl["error"]["message"], payload={"endpoint": endpoint})
        return rl

    objs = _load("ad_objects.json")
    accounts = _load("ad_accounts.json")

    # Resolve account: allow account_id to be internal id or external act_*
    acct = None
    if account_id is not None:
        if not isinstance(account_id, str) or not account_id.strip():
            _append_audit("failed", auth_session_id=session.get("id"), error_message="account_id must be a non-empty string when provided", payload={"endpoint": endpoint})
            return _err("VALIDATION_ERROR", "account_id must be a non-empty string when provided")
        aid = account_id.strip()
        acct = next((a for a in accounts if a.get("id") == aid or a.get("external_meta_account_id") == aid), None)
        if acct is None:
            _append_audit("failed", auth_session_id=session.get("id"), error_message="Ad account not found", payload={"endpoint": endpoint, "account_id": account_id})
            return _err("NOT_FOUND", "Ad account not found", account_id=account_id)
    else:
        # pick an account tied to this auth_session, else any active account
        acct = next((a for a in accounts if a.get("auth_session_id") == session.get("id") and a.get("status") == "active"), None) or next((a for a in accounts if a.get("status") == "active"), None)
        if acct is None:
            _append_audit("failed", auth_session_id=session.get("id"), error_message="No ad account available", payload={"endpoint": endpoint})
            return _err("UNAUTHORIZED", "No ad account available for this caller")

    account_row_id = acct.get("id")

    # Resolve adset: required by business rule; allow null by selecting a valid existing adset for that account
    adset_row = None
    adset_external_id = None
    if adset_id is not None:
        if not isinstance(adset_id, str) or not adset_id.strip():
            _append_audit("failed", auth_session_id=session.get("id"), account_row_id=account_row_id, error_message="adset_id must be a non-empty string when provided", payload={"endpoint": endpoint})
            return _err("VALIDATION_ERROR", "adset_id must be a non-empty string when provided")
        adset_external_id = adset_id.strip()
        adset_row = next((r for r in objs if r.get("object_type") == "adset" and (r.get("external_meta_id") == adset_external_id or r.get("id") == adset_external_id) and r.get("account_id") == account_row_id), None)
        if adset_row is None:
            _append_audit("failed", auth_session_id=session.get("id"), account_row_id=account_row_id, error_message="Referenced adset not found for account", payload={"endpoint": endpoint, "adset_id": adset_external_id})
            return _err("NOT_FOUND", "Referenced ad set not found for this account", adset_id=adset_external_id, account_id=account_row_id)
        adset_external_id = adset_row.get("external_meta_id")
    else:
        # pick newest adset for the account
        candidates = [r for r in objs if r.get("object_type") == "adset" and r.get("account_id") == account_row_id]
        def _k(r):
            return _parse_dt_any(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        candidates.sort(key=_k, reverse=True)
        adset_row = candidates[0] if candidates else None
        if adset_row is None:
            _append_audit("failed", auth_session_id=session.get("id"), account_row_id=account_row_id, error_message="No adset exists to create an ad under", payload={"endpoint": endpoint})
            return _err("NOT_FOUND", "Referenced ad set not found for this account", adset_id=None, account_id=account_row_id)
        adset_external_id = adset_row.get("external_meta_id")

    # Derive campaign id from adset for constraint
    parent_campaign_external_id = adset_row.get("parent_campaign_external_id")

    if creative_id is not None and (not isinstance(creative_id, str) or not creative_id.strip()):
        _append_audit("failed", auth_session_id=session.get("id"), account_row_id=account_row_id, error_message="creative_id must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "creative_id must be a non-empty string when provided")
    creative_external_id = creative_id.strip() if isinstance(creative_id, str) else None
    if creative_external_id is None:
        # allow creation even without explicit creative_id if we can find an existing creative asset for the account
        creatives = _load("creative_assets.json")
        cands = [c for c in creatives if c.get("asset_type") == "ad_creative" and c.get("account_id") == account_row_id and c.get("external_meta_id")]
        cands.sort(key=lambda r: _parse_dt_any(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=True)
        if cands:
            creative_external_id = cands[0].get("external_meta_id")

    if creative_external_id is None:
        _append_audit("failed", auth_session_id=session.get("id"), account_row_id=account_row_id, error_message="No creative_id provided and no cached creative available", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "creative_id is required (or a cached creative must exist) to create an ad")

    # Unique constraint unique(object_type, external_meta_id) - we generate a new external id
    new_external = "ad_" + uuid.uuid4().hex[:18]
    while any(r.get("object_type") == "ad" and r.get("external_meta_id") == new_external for r in objs):
        new_external = "ad_" + uuid.uuid4().hex[:18]

    now = _now_iso()
    new_row = {
        "id": "meta_obj_" + uuid.uuid4().hex,
        "account_id": account_row_id,
        "object_type": "ad",
        "external_meta_id": new_external,
        "parent_campaign_external_id": parent_campaign_external_id,
        "parent_adset_external_id": adset_external_id,
        "name": (name.strip() if isinstance(name, str) and name.strip() else f"Ad {new_external}"),
        "objective": None,
        "buying_type": None,
        "bid_strategy": None,
        "bid_cap": None,
        "bid_amount_minor": None,
        "daily_budget_minor_str": None,
        "lifetime_budget_minor_str": None,
        "spend_cap_minor_str": None,
        "campaign_budget_optimization": None,
        "special_ad_categories": None,
        "ab_test_control_setups": None,
        "targeting": None,
        "optimization_goal": None,
        "billing_event": None,
        "start_time": None,
        "end_time": None,
        "frequency_control_specs": None,
        "creative_external_id": creative_external_id,
        "tracking_specs": tracking_specs,
        "configured_status": status,
        "effective_status": None,
        "status": "active",
        "last_synced_at": None,
        "created_at": now,
        "updated_at": now
    }
    if bid_amount is not None:
        new_row["bid_amount_minor"] = int(bid_amount.strip())

    objs.append(new_row)
    _save("ad_objects.json", objs)

    session["last_used_at"] = now
    session["updated_at"] = now
    sessions = _load("meta_auth_sessions.json")
    for i, s in enumerate(sessions):
        if s.get("id") == session.get("id"):
            sessions[i] = session
            _save("meta_auth_sessions.json", sessions)
            break

    _append_audit("succeeded", auth_session_id=session.get("id"), account_row_id=account_row_id, object_id=new_external, payload={"latency_ms": int((time.time() - t0) * 1000), "created_ad": new_row})
    return {"id": new_external, "ad": new_row, "latency_ms": int((time.time() - t0) * 1000)}

def get_ad_creatives(access_token=None, ad_id=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_ad_creatives"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_value, auth_session_id=None, account_row_id=None, object_id=None, error_message=None, result_payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "ad",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": result_payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _log("failed", error_message="Invalid access_token", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if ad_id is not None and (not isinstance(ad_id, str) or not ad_id.strip()):
        _log("failed", error_message="Invalid ad_id", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "ad_id must be a non-empty string when provided")

    sessions = _load("meta_auth_sessions.json")
    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp is not None and exp <= datetime.datetime.now(datetime.timezone.utc):
            return False
        if not s.get("access_token_ciphertext") and access_token is None:
            return False
        return True

    resolved = None
    if access_token is not None:
        tok = access_token.strip()
        for s in sessions:
            if isinstance(s, dict) and (s.get("id") == tok or (s.get("access_token_ciphertext") and s.get("access_token_ciphertext") == tok)):
                if _session_valid(s) or s.get("status") == "active":
                    resolved = s
                    break
        if resolved is None:
            valid = [s for s in sessions if _session_valid(s)]
            if valid:
                valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
                resolved = valid[0]
    else:
        valid = [s for s in sessions if _session_valid(s)]
        if valid:
            valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            resolved = valid[0]
    if resolved is None:
        _log("failed", error_message="No valid Meta auth session", result_payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("UNAUTHORIZED", "No valid Meta access token available (no active auth session)")

    ad_objects = _load("ad_objects.json")
    creative_assets = _load("creative_assets.json")
    accounts = _load("ad_accounts.json")

    ad_row = None
    if ad_id is not None:
        aid = ad_id.strip()
        for o in ad_objects:
            if isinstance(o, dict) and o.get("object_type") == "ad" and o.get("external_meta_id") == aid and o.get("status") != "deleted":
                ad_row = o
                break
        if ad_row is None:
            _log("failed", auth_session_id=resolved.get("id"), object_id=aid, error_message="Ad not found",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "Ad not found")
    else:
        cand = [o for o in ad_objects if isinstance(o, dict) and o.get("object_type") == "ad" and o.get("status") != "deleted"]
        if not cand:
            _log("failed", auth_session_id=resolved.get("id"), error_message="No ads available",
                 result_payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "No cached ads available")
        cand.sort(key=lambda r: (r.get("updated_at") or r.get("created_at") or ""), reverse=True)
        ad_row = cand[0]

    acct_row = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == ad_row.get("account_id"):
            acct_row = a
            break

    creative_external_id = ad_row.get("creative_external_id")
    if not creative_external_id:
        now = _now_iso()
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == resolved.get("id"):
                s["last_used_at"] = now
                s["updated_at"] = now
                break
        _save("meta_auth_sessions.json", sessions)
        _log("succeeded", auth_session_id=resolved.get("id"), account_row_id=(acct_row.get("id") if acct_row else None),
             object_id=ad_row.get("external_meta_id"),
             result_payload={"returned": 0, "latency_ms": int((time.time()-t0)*1000)})
        return {"creatives": [], "meta": {"resolved_auth_session_id": resolved.get("id"), "latency_ms": int((time.time()-t0)*1000)}}

    # find or create a creative_assets row keyed by (account_id, asset_type, external_meta_id)
    existing = None
    for ca in creative_assets:
        if not isinstance(ca, dict):
            continue
        if ca.get("asset_type") == "ad_creative" and ca.get("account_id") == ad_row.get("account_id") and ca.get("external_meta_id") == creative_external_id:
            existing = ca
            break

    now = _now_iso()
    if existing is None:
        new_row = {
            "id": "meta_asset_" + uuid.uuid4().hex,
            "account_id": ad_row.get("account_id"),
            "asset_type": "ad_creative",
            "external_meta_id": creative_external_id,
            "name": None,
            "page_id": None,
            "instagram_actor_id": None,
            "image_hash": None,
            "image_source_path": None,
            "snapshot_url": None,
            "local_file_path": None,
            "output_dir": None,
            "mime_type": None,
            "byte_size": None,
            "link_url": None,
            "message": None,
            "headline": None,
            "description": None,
            "call_to_action_type": None,
            "raw_meta_payload": {"resolved_from_ad_id": ad_row.get("external_meta_id")},
            "status": "active",
            "failure_reason": None,
            "created_at": now,
            "updated_at": now
        }
        creative_assets.append(new_row)
        _save("creative_assets.json", creative_assets)
        creatives = [new_row]
    else:
        existing["updated_at"] = now
        _save("creative_assets.json", creative_assets)
        creatives = [existing]

    for s in sessions:
        if isinstance(s, dict) and s.get("id") == resolved.get("id"):
            s["last_used_at"] = now
            s["updated_at"] = now
            break
    _save("meta_auth_sessions.json", sessions)

    _log("succeeded", auth_session_id=resolved.get("id"), account_row_id=(acct_row.get("id") if acct_row else None),
         object_id=ad_row.get("external_meta_id"),
         result_payload={"returned": len(creatives), "latency_ms": int((time.time()-t0)*1000)})

    return {"creatives": creatives, "meta": {"resolved_auth_session_id": resolved.get("id"), "latency_ms": int((time.time()-t0)*1000)}}

def get_ad_image(access_token=None, ad_id=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_ad_image"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "image_download_debug",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or (ad_id if ad_id else endpoint),
            "time_range": None,
            "breakdown": None,
            "level": None,
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        window_s = 60
        limit_per_window = 60
        cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("job_type") not in ("insights_query", "ads_archive_search", "image_download_debug"):
                continue
            if (r.get("auth_session_id") or None) != (auth_session_id or None):
                continue
            ts = _parse_dt_any(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_s, limit=limit_per_window)
        return None

    def _resolve_session(token_param):
        sessions = _load("meta_auth_sessions.json")

        def _valid(s):
            if not isinstance(s, dict):
                return False
            if s.get("status") != "active":
                return False
            exp = _parse_dt_any(s.get("token_expires_at"))
            if exp is not None and exp <= _now_dt():
                return False
            if not s.get("access_token_ciphertext"):
                return False
            return True

        if token_param is not None:
            if not isinstance(token_param, str) or not token_param.strip():
                return None
            tok = token_param.strip()
            for s in sessions:
                if (s.get("id") == tok or s.get("access_token_ciphertext") == tok) and _valid(s):
                    return s
            return None

        for s in sessions:
            if _valid(s):
                return s
        return None

    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if ad_id is not None and (not isinstance(ad_id, str) or not ad_id.strip()):
        _append_audit("failed", error_message="ad_id must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "ad_id must be a non-empty string when provided")
    ad_id = ad_id.strip() if isinstance(ad_id, str) else None

    session = _resolve_session(access_token)
    if session is None:
        _append_audit("failed", error_message="No valid cached Meta auth session available", payload={"endpoint": endpoint, "ad_id": ad_id})
        return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    rl = _rate_limit_check(session.get("id"))
    if rl:
        _append_audit("failed", auth_session_id=session.get("id"), error_message=rl["error"]["message"], payload={"endpoint": endpoint})
        return rl

    objs = _load("ad_objects.json")
    creatives = _load("creative_assets.json")
    accounts = _load("ad_accounts.json")

    # Resolve ad: allow null by selecting a real ad that has creative_external_id
    ad_row = None
    if ad_id:
        ad_row = next((r for r in objs if r.get("object_type") == "ad" and (r.get("external_meta_id") == ad_id or r.get("id") == ad_id)), None)
    else:
        candidates = [r for r in objs if r.get("object_type") == "ad" and r.get("creative_external_id")]
        candidates.sort(key=lambda r: _parse_dt_any(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=True)
        ad_row = candidates[0] if candidates else None
        ad_id = ad_row.get("external_meta_id") if ad_row else None

    if ad_row is None:
        _append_audit("failed", auth_session_id=session.get("id"), error_message="Ad not found", payload={"endpoint": endpoint, "ad_id": ad_id})
        return _err("NOT_FOUND", "Ad not found", ad_id=ad_id)

    acct_row_id = ad_row.get("account_id")
    acct = next((a for a in accounts if a.get("id") == acct_row_id), None)

    creative_external_id = ad_row.get("creative_external_id")
    if not creative_external_id:
        _append_audit("succeeded", auth_session_id=session.get("id"), account_row_id=acct_row_id, object_id=ad_id, payload={"creative_external_id": None, "image": None})
        return {"ad_id": ad_id, "creative_external_id": None, "image": None}

    # Find any snapshot already cached; otherwise infer from any stored creative payloads.
    snapshot = next((c for c in creatives if c.get("asset_type") == "ad_image_snapshot" and isinstance(c.get("raw_meta_payload"), dict) and c.get("raw_meta_payload", {}).get("ad_id") == ad_id), None)
    if snapshot is None:
        # fallback: any creative row with snapshot_url
        snapshot = next((c for c in creatives if c.get("asset_type") in ("ad_creative", "ad_image_snapshot") and c.get("external_meta_id") == creative_external_id and c.get("snapshot_url")), None)

    if snapshot is None:
        # Create a placeholder snapshot row (cache miss) rather than failing validation.
        now = _now_iso()
        snapshot = {
            "id": "meta_asset_" + uuid.uuid4().hex,
            "account_id": acct_row_id,
            "asset_type": "ad_image_snapshot",
            "external_meta_id": None,
            "name": None,
            "page_id": None,
            "instagram_actor_id": None,
            "image_hash": None,
            "image_source_path": None,
            "snapshot_url": None,
            "local_file_path": None,
            "output_dir": None,
            "mime_type": None,
            "byte_size": None,
            "link_url": None,
            "message": None,
            "headline": None,
            "description": None,
            "call_to_action_type": None,
            "raw_meta_payload": {"ad_id": ad_id, "creative_external_id": creative_external_id, "note": "snapshot not yet fetched in offline store"},
            "status": "processing",
            "failure_reason": None,
            "created_at": now,
            "updated_at": now
        }
        creatives.append(snapshot)
        _save("creative_assets.json", creatives)

    # Mark last used
    session["last_used_at"] = _now_iso()
    session["updated_at"] = _now_iso()
    sessions = _load("meta_auth_sessions.json")
    for i, s in enumerate(sessions):
        if s.get("id") == session.get("id"):
            sessions[i] = session
            _save("meta_auth_sessions.json", sessions)
            break

    payload = {
        "ad_id": ad_id,
        "creative_external_id": creative_external_id,
        "snapshot_url": snapshot.get("snapshot_url"),
        "local_file_path": snapshot.get("local_file_path"),
        "mime_type": snapshot.get("mime_type"),
        "byte_size": snapshot.get("byte_size"),
        "asset_id": snapshot.get("id"),
        "asset_status": snapshot.get("status")
    }
    _append_audit("succeeded", auth_session_id=session.get("id"), account_row_id=acct_row_id, object_id=ad_id, payload={"latency_ms": int((time.time() - t0) * 1000), **payload})
    return {"image": payload, "latency_ms": int((time.time() - t0) * 1000)}

def save_ad_image_locally(access_token=None, ad_id=None, output_dir=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "save_ad_image_locally"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "image_download_debug",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or (ad_id if ad_id else endpoint),
            "time_range": None,
            "breakdown": None,
            "level": None,
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        window_s = 60
        limit_per_window = 60
        cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("job_type") not in ("insights_query", "ads_archive_search", "image_download_debug"):
                continue
            if (r.get("auth_session_id") or None) != (auth_session_id or None):
                continue
            ts = _parse_dt_any(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_s, limit=limit_per_window)
        return None

    def _resolve_session(token_param):
        sessions = _load("meta_auth_sessions.json")

        def _valid(s):
            if not isinstance(s, dict):
                return False
            if s.get("status") != "active":
                return False
            exp = _parse_dt_any(s.get("token_expires_at"))
            if exp is not None and exp <= _now_dt():
                return False
            if not s.get("access_token_ciphertext"):
                return False
            return True

        if token_param is not None:
            if not isinstance(token_param, str) or not token_param.strip():
                return None
            tok = token_param.strip()
            for s in sessions:
                if (s.get("id") == tok or s.get("access_token_ciphertext") == tok) and _valid(s):
                    return s
            return None

        for s in sessions:
            if _valid(s):
                return s
        return None

    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")
    if ad_id is not None and (not isinstance(ad_id, str) or not ad_id.strip()):
        _append_audit("failed", error_message="ad_id must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "ad_id must be a non-empty string when provided")
    ad_id = ad_id.strip() if isinstance(ad_id, str) else None

    if output_dir is None:
        output_dir = "ad_images"
    if not isinstance(output_dir, str) or not output_dir.strip():
        _append_audit("failed", error_message="output_dir must be a non-empty string", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "output_dir must be a non-empty string")
    output_dir = output_dir.strip()

    session = _resolve_session(access_token)
    if session is None:
        _append_audit("failed", error_message="No valid cached Meta auth session available", payload={"endpoint": endpoint, "ad_id": ad_id})
        return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    rl = _rate_limit_check(session.get("id"))
    if rl:
        _append_audit("failed", auth_session_id=session.get("id"), error_message=rl["error"]["message"], payload={"endpoint": endpoint})
        return rl

    objs = _load("ad_objects.json")
    assets = _load("creative_assets.json")

    ad_row = None
    if ad_id:
        ad_row = next((r for r in objs if r.get("object_type") == "ad" and (r.get("external_meta_id") == ad_id or r.get("id") == ad_id)), None)
    else:
        candidates = [r for r in objs if r.get("object_type") == "ad"]
        candidates.sort(key=lambda r: _parse_dt_any(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=True)
        ad_row = candidates[0] if candidates else None
        ad_id = ad_row.get("external_meta_id") if ad_row else None

    if ad_row is None:
        _append_audit("failed", auth_session_id=session.get("id"), error_message="Ad not found", payload={"endpoint": endpoint, "ad_id": ad_id})
        return _err("NOT_FOUND", "Ad not found", ad_id=ad_id)

    acct_row_id = ad_row.get("account_id")
    creative_external_id = ad_row.get("creative_external_id")

    # Find or create snapshot asset for this ad
    snap = next((a for a in assets if a.get("asset_type") == "ad_image_snapshot" and isinstance(a.get("raw_meta_payload"), dict) and a.get("raw_meta_payload", {}).get("ad_id") == ad_id), None)
    now = _now_iso()
    if snap is None:
        snap = {
            "id": "meta_asset_" + uuid.uuid4().hex,
            "account_id": acct_row_id,
            "asset_type": "ad_image_snapshot",
            "external_meta_id": None,
            "name": None,
            "page_id": None,
            "instagram_actor_id": None,
            "image_hash": None,
            "image_source_path": None,
            "snapshot_url": None,
            "local_file_path": None,
            "output_dir": None,
            "mime_type": None,
            "byte_size": None,
            "link_url": None,
            "message": None,
            "headline": None,
            "description": None,
            "call_to_action_type": None,
            "raw_meta_payload": {"ad_id": ad_id, "creative_external_id": creative_external_id},
            "status": "processing",
            "failure_reason": None,
            "created_at": now,
            "updated_at": now
        }
        assets.append(snap)

    # Offline behavior: "save locally" records intended file path; does not fetch network bytes.
    # Create directory and write a tiny placeholder file to make the effect observable.
    try:
        os.makedirs(output_dir, exist_ok=True)
    except Exception:
        snap["status"] = "failed"
        snap["failure_reason"] = f"Unable to create output_dir: {output_dir}"
        snap["output_dir"] = output_dir
        snap["updated_at"] = now
        _save("creative_assets.json", assets)
        _append_audit("failed", auth_session_id=session.get("id"), account_row_id=acct_row_id, object_id=ad_id, error_message=snap["failure_reason"], payload={"endpoint": endpoint})
        return _err("CONFLICT", "Unable to create output directory", output_dir=output_dir)

    file_path = os.path.join(output_dir, f"{ad_id}.img")
    try:
        with open(file_path, "wb") as f:
            f.write(b"")  # placeholder
    except Exception:
        snap["status"] = "failed"
        snap["failure_reason"] = f"Unable to write file: {file_path}"
        snap["output_dir"] = output_dir
        snap["updated_at"] = now
        _save("creative_assets.json", assets)
        _append_audit("failed", auth_session_id=session.get("id"), account_row_id=acct_row_id, object_id=ad_id, error_message=snap["failure_reason"], payload={"endpoint": endpoint})
        return _err("CONFLICT", "Unable to write image file", file_path=file_path)

    snap["local_file_path"] = file_path
    snap["output_dir"] = output_dir
    snap["status"] = "active"
    snap["failure_reason"] = None
    snap["updated_at"] = now
    _save("creative_assets.json", assets)

    session["last_used_at"] = now
    session["updated_at"] = now
    sessions = _load("meta_auth_sessions.json")
    for i, s in enumerate(sessions):
        if s.get("id") == session.get("id"):
            sessions[i] = session
            _save("meta_auth_sessions.json", sessions)
            break

    _append_audit("succeeded", auth_session_id=session.get("id"), account_row_id=acct_row_id, object_id=ad_id, payload={"latency_ms": int((time.time() - t0) * 1000), "local_file_path": file_path})
    return {"ad_id": ad_id, "local_file_path": file_path, "latency_ms": int((time.time() - t0) * 1000)}

def update_ad(ad_id, status=None, bid_amount=None, tracking_specs=None, access_token=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_ad"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        job = {
            "id": _gen_id("aa"),
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "ad",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        rows.append(job)
        _save("analytics_and_archive.json", rows)
        return job

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        now = _now_dt()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("auth_session_id") != auth_session_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    # Validate ad_id
    if ad_id is None or (isinstance(ad_id, str) and ad_id.strip() == ""):
        _append_audit("failed", object_id=ad_id or None, error_message="ad_id is required")
        return _err("VALIDATION_ERROR", "ad_id is required", ad_id=ad_id)
    if not isinstance(ad_id, str):
        _append_audit("failed", object_id=str(ad_id), error_message="ad_id must be a string")
        return _err("VALIDATION_ERROR", "ad_id must be a string", ad_id=ad_id)

    # Validate fields
    if status is not None and not isinstance(status, str):
        _append_audit("failed", object_id=ad_id, error_message="status must be a string")
        return _err("VALIDATION_ERROR", "status must be a string")
    if bid_amount is not None:
        if not isinstance(bid_amount, int):
            _append_audit("failed", object_id=ad_id, error_message="bid_amount must be an integer")
            return _err("VALIDATION_ERROR", "bid_amount must be an integer")
        if bid_amount < 0:
            _append_audit("failed", object_id=ad_id, error_message="bid_amount must be non-negative")
            return _err("VALIDATION_ERROR", "bid_amount must be non-negative")

    parsed_tracking_specs = None
    if tracking_specs is not None:
        if isinstance(tracking_specs, str):
            # Must parse JSON string into array of objects
            try:
                parsed = json.loads(tracking_specs)
            except json.JSONDecodeError:
                _append_audit("failed", object_id=ad_id, error_message="tracking_specs must be valid JSON when provided as a string")
                return _err("VALIDATION_ERROR", "tracking_specs must be valid JSON when provided as a string")
            if not isinstance(parsed, list) or any(not isinstance(x, dict) for x in parsed):
                _append_audit("failed", object_id=ad_id, error_message="tracking_specs must parse to an array of objects")
                return _err("VALIDATION_ERROR", "tracking_specs must parse to an array of objects")
            parsed_tracking_specs = parsed
        else:
            _append_audit("failed", object_id=ad_id, error_message="tracking_specs must be a JSON string")
            return _err("VALIDATION_ERROR", "tracking_specs must be a JSON string")

    update_fields_present = any(v is not None for v in [status, bid_amount, tracking_specs])

    # Resolve auth
    auth_rows = _load("meta_auth_sessions.json")
    now_dt = _now_dt()

    def _is_session_usable(s):
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp and exp <= now_dt:
            return False
        return True

    auth_session = None
    if access_token is not None:
        if not isinstance(access_token, str):
            _append_audit("failed", object_id=ad_id, error_message="access_token must be a string")
            return _err("VALIDATION_ERROR", "access_token must be a string")
        for s in auth_rows:
            if not _is_session_usable(s):
                continue
            if access_token == s.get("id") or access_token == s.get("access_token_ciphertext"):
                auth_session = s
                break
        if auth_session is None:
            auth_session = {"id": None}
    else:
        for s in auth_rows:
            if _is_session_usable(s):
                auth_session = s
                break
        if auth_session is None:
            _append_audit("failed", object_id=ad_id, error_message="No active Meta auth session available")
            return _err("UNAUTHORIZED", "No active Meta auth session available")

    ok, rl_err = _rate_limit_check(auth_session.get("id"))
    if not ok:
        _append_audit("failed", auth_session_id=auth_session.get("id"), object_id=ad_id, error_message=rl_err["error"]["message"])
        return rl_err

    objs = _load("ad_objects.json")
    ad = None
    for r in objs:
        if r.get("object_type") == "ad" and r.get("external_meta_id") == ad_id:
            ad = r
            break
    if ad is None:
        for r in objs:
            if r.get("object_type") == "ad" and r.get("id") == ad_id:
                ad = r
                break
    if ad is None:
        _append_audit("failed", auth_session_id=auth_session.get("id"), object_id=ad_id, error_message="Ad not found")
        return _err("NOT_FOUND", "Ad not found", ad_id=ad_id)

    if not update_fields_present:
        if auth_session.get("id"):
            for s in auth_rows:
                if s.get("id") == auth_session["id"]:
                    s["last_used_at"] = _now_iso()
                    s["updated_at"] = _now_iso()
                    break
            _save("meta_auth_sessions.json", auth_rows)
        payload = {"ad": ad, "updated": False}
        _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=ad.get("account_id"), object_id=ad.get("external_meta_id") or ad.get("id"), payload=payload)
        return payload

    # configured_status transition rules
    if status is not None:
        allowed_statuses = {"ACTIVE", "PAUSED", "DELETED", "ARCHIVED"}
        if status not in allowed_statuses:
            _append_audit("failed", auth_session_id=auth_session.get("id"), account_row_id=ad.get("account_id"), object_id=ad_id, error_message="Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_statuses)))
        current = ad.get("configured_status")
        transitions = {
            "PAUSED": {"ACTIVE", "ARCHIVED", "DELETED"},
            "ACTIVE": {"PAUSED", "ARCHIVED", "DELETED"},
            "ARCHIVED": {"PAUSED", "DELETED"},
            "DELETED": set()
        }
        if current in transitions and status != current and status not in transitions[current]:
            _append_audit("failed", auth_session_id=auth_session.get("id"), account_row_id=ad.get("account_id"), object_id=ad_id, error_message="Invalid status transition")
            return _err("INVALID_TRANSITION", f"Invalid configured_status transition from {current} to {status}", from_status=current, to_status=status)

    changed = False
    if bid_amount is not None and bid_amount != ad.get("bid_amount_minor"):
        ad["bid_amount_minor"] = bid_amount
        changed = True
    if parsed_tracking_specs is not None and parsed_tracking_specs != ad.get("tracking_specs"):
        ad["tracking_specs"] = parsed_tracking_specs
        changed = True
    if status is not None and status != ad.get("configured_status"):
        ad["configured_status"] = status
        changed = True

    if not changed:
        if auth_session.get("id"):
            for s in auth_rows:
                if s.get("id") == auth_session["id"]:
                    s["last_used_at"] = _now_iso()
                    s["updated_at"] = _now_iso()
                    break
            _save("meta_auth_sessions.json", auth_rows)
        payload = {"ad": ad, "updated": False}
        _append_audit("succeeded", auth_session_id=auth_session.get("id"), account_row_id=ad.get("account_id"), object_id=ad.get("external_meta_id") or ad.get("id"), payload=payload)
        return payload

    ad["updated_at"] = _now_iso()
    for i in range(len(objs)):
        if objs[i].get("id") == ad.get("id"):
            objs[i] = ad
            break
    _save("ad_objects.json", objs)

    if auth_session.get("id"):
        for s in auth_rows:
            if s.get("id") == auth_session["id"]:
                s["last_used_at"] = _now_iso()
                s["updated_at"] = _now_iso()
                break
        _save("meta_auth_sessions.json", auth_rows)

