            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "upload_ad_image"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        job = {
            "id": _gen_id("aa"),
            "job_type": "image_download_debug",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": endpoint,
            "time_range": None,
            "breakdown": None,
            "level": None,
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        rows.append(job)
        _save("analytics_and_archive.json", rows)
        return job

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        now = _now_dt()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("auth_session_id") != auth_session_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    # Validate minimal inputs (relaxed but must have effect)
    if account_id is None or (isinstance(account_id, str) and account_id.strip() == ""):
        _append_audit("failed", error_message="account_id is required")
        return _err("VALIDATION_ERROR", "account_id is required", account_id=account_id)
    if not isinstance(account_id, str):
        _append_audit("failed", error_message="account_id must be a string")
        return _err("VALIDATION_ERROR", "account_id must be a string", account_id=account_id)

    if image_path is None or (isinstance(image_path, str) and image_path.strip() == ""):
        _append_audit("failed", error_message="image_path is required", account_row_id=None)
        return _err("VALIDATION_ERROR", "image_path is required", image_path=image_path)
    if not isinstance(image_path, str):
        _append_audit("failed", error_message="image_path must be a string")
        return _err("VALIDATION_ERROR", "image_path must be a string")

    if name is not None and not isinstance(name, str):
        _append_audit("failed", error_message="name must be a string")
        return _err("VALIDATION_ERROR", "name must be a string")

    # Resolve auth
    auth_rows = _load("meta_auth_sessions.json")
    now_dt = _now_dt()

    def _is_session_usable(s):
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp and exp <= now_dt:
            return False
        return True

    auth_session = None
    if access_token is not None:
        if not isinstance(access_token, str):
            _append_audit("failed", error_message="access_token must be a string")
            return _err("VALIDATION_ERROR", "access_token must be a string")
        for s in auth_rows:
            if not _is_session_usable(s):
                continue
            if access_token == s.get("id") or access_token == s.get("access_token_ciphertext"):
                auth_session = s
                break
        if auth_session is None:
            auth_session = {"id": None}
    else:
        for s in auth_rows:
            if _is_session_usable(s):
                auth_session = s
                break
        if auth_session is None:
            _append_audit("failed", error_message="No active Meta auth session available")
            return _err("UNAUTHORIZED", "No active Meta auth session available")

    ok, rl_err = _rate_limit_check(auth_session.get("id"))
    if not ok:
        _append_audit("failed", auth_session_id=auth_session.get("id"), error_message=rl_err["error"]["message"])
        return rl_err

    # Resolve account row: accept internal id OR external act_ id
    accts = _load("ad_accounts.json")
    acct = None
    for a in accts:
        if a.get("id") == account_id or a.get("external_meta_account_id") == account_id:
            acct = a
            break
    if acct is None:
        _append_audit("failed", auth_session_id=auth_session.get("id"), error_message="Ad account not found")
        return _err("NOT_FOUND", "Ad account not found", account_id=account_id)

    # Simulate upload result offline: if local file exists, succeed; else fail (and record failure_reason)
    assets = _load("creative_assets.json")
    now = _now_iso()

    image_hash = None
    status_val = "failed"
    failure_reason = None
    try:
        if os.path.exists(image_path) and os.path.isfile(image_path):
            h = hashlib.sha256()
            with open(image_path, "rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
            image_hash = h.hexdigest()[:32]
            status_val = "active"
        else:
            failure_reason = "File not found"
    except OSError as e:
        failure_reason = f"File read error: {e}"

    # Upsert unique(account_id, asset_type, external_meta_id) where external_meta_id not null doesn't apply here
    # For uploads, we key by (account_id, asset_type, image_hash)
    existing = None
    if image_hash:
        for r in assets:
            if r.get("asset_type") == "image_upload" and r.get("account_id") == acct.get("id") and r.get("image_hash") == image_hash and r.get("status") != "deleted":
                existing = r
                break

    if existing is None:
        row = {
            "id": _gen_id("ca"),
            "account_id": acct.get("id"),
            "asset_type": "image_upload",
            "external_meta_id": None,
            "name": name,
            "page_id": None,
            "instagram_actor_id": None,
            "image_hash": image_hash,
            "image_source_path": image_path,
            "snapshot_url": None,
            "local_file_path": None,
            "output_dir": None,
            "mime_type": None,
            "byte_size": None,
            "link_url": None,
            "message": None,
            "headline": None,
            "description": None,
            "call_to_action_type": None,
            "raw_meta_payload": {"endpoint": endpoint, "account_id": acct.get("external_meta_account_id"), "name": name},
            "status": status_val,
            "failure_reason": failure_reason,
            "created_at": now,
            "updated_at": now
        }
        assets.append(row)
        _save("creative_assets.json", assets)
    else:
        existing["updated_at"] = now
        existing["name"] = name if name is not None else existing.get("name")
        existing["image_source_path"] = image_path
        existing["status"] = status_val
        existing["failure_reason"] = failure_reason
        _save("creative_assets.json", assets)
        row = existing

    if auth_session.get("id"):
        for s in auth_rows:
            if s.get("id") == auth_session["id"]:
                s["last_used_at"] = now
                s["updated_at"] = now
                break
        _save("meta_auth_sessions.json", auth_rows)

    payload = {"image": row, "image_hash": image_hash, "status": status_val, "latency_ms": int((time.time() - t0) * 1000)}
    _append_audit("succeeded" if status_val == "active" else "failed", auth_session_id=auth_session.get("id"), account_row_id=acct.get("id"), payload=payload, error_message=failure_reason)
    if status_val != "active":
        return _err("CONFLICT", "Image upload failed", failure_reason=failure_reason, image_path=image_path)
    return payload

