def get_account_pages(access_token=None, account_id=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_account_pages"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_value, auth_session_id=None, account_row_id=None, object_id=None, error_message=None, payload=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "image_download_debug",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": None,
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": endpoint,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _log("failed", error_message="Invalid access_token", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    if account_id is not None:
        if not isinstance(account_id, str) or not account_id.strip():
            _log("failed", error_message="Invalid account_id", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be a non-empty string when provided")
        if not re.match(r"^act_\d+$", account_id.strip()):
            _log("failed", error_message="Invalid account_id format", payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("VALIDATION_ERROR", "account_id must be in act_XXXXXXXX format")

    # ---- resolve auth session ----
    sessions = _load("meta_auth_sessions.json")
    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp is not None and exp <= datetime.datetime.now(datetime.timezone.utc):
            return False
        if not s.get("access_token_ciphertext") and access_token is None:
            return False
        return True

    resolved = None
    if access_token is not None:
        tok = access_token.strip()
        for s in sessions:
            if isinstance(s, dict) and (s.get("id") == tok or (s.get("access_token_ciphertext") and s.get("access_token_ciphertext") == tok)):
                if _session_valid(s) or s.get("status") == "active":
                    resolved = s
                    break
        if resolved is None:
            valid = [s for s in sessions if _session_valid(s)]
            if valid:
                valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
                resolved = valid[0]
    else:
        valid = [s for s in sessions if _session_valid(s)]
        if valid:
            valid.sort(key=lambda r: (r.get("last_used_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            resolved = valid[0]

    if resolved is None:
        _log("failed", error_message="No valid Meta auth session", payload={"latency_ms": int((time.time()-t0)*1000)})
        return _err("UNAUTHORIZED", "No valid Meta access token available (no active auth session)")

    # ---- resolve account (allow omission) ----
    accounts = _load("ad_accounts.json")
    acct = None
    if account_id is not None:
        aid = account_id.strip()
        for a in accounts:
            if isinstance(a, dict) and a.get("external_meta_account_id") == aid:
                acct = a
                break
        if acct is None:
            _log("failed", auth_session_id=resolved.get("id"), object_id=aid, error_message="Account not found",
                 payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "Ad account not found for the given account_id")
    else:
        cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active" and a.get("auth_session_id") == resolved.get("id")]
        if not cand:
            cand = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if cand:
            cand.sort(key=lambda r: (r.get("last_synced_at") or r.get("updated_at") or r.get("created_at") or ""), reverse=True)
            acct = cand[0]
        if acct is None:
            _log("failed", auth_session_id=resolved.get("id"), error_message="No ad accounts available",
                 payload={"latency_ms": int((time.time()-t0)*1000)})
            return _err("NOT_FOUND", "No cached ad accounts available")

    # Pages are stored as creative_assets of type 'page' for the account.
    creative_assets = _load("creative_assets.json")
    pages = []
    for ca in creative_assets:
        if not isinstance(ca, dict):
            continue
        if ca.get("asset_type") == "page" and ca.get("account_id") == acct.get("id") and ca.get("status") != "deleted":
            pages.append(ca)

    pages.sort(key=lambda r: (r.get("updated_at") or r.get("created_at") or ""), reverse=True)

    now = _now_iso()
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == resolved.get("id"):
            s["last_used_at"] = now
            s["updated_at"] = now
            break
    _save("meta_auth_sessions.json", sessions)

    _log("succeeded", auth_session_id=resolved.get("id"), account_row_id=acct.get("id"), object_id=acct.get("external_meta_account_id"),
         payload={"returned": len(pages), "latency_ms": int((time.time()-t0)*1000)})

    return {"pages": pages, "meta": {"resolved_auth_session_id": resolved.get("id"), "latency_ms": int((time.time()-t0)*1000)}}

def get_insights(access_token=None, object_id=None, time_range="maximum", breakdown="", level="ad", **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_insights"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _normalize_time_range(tr):
        if tr is None:
            return {"preset": "maximum"}
        if isinstance(tr, str):
            if not tr.strip():
                return {"preset": "maximum"}
            return {"preset": tr}
        if isinstance(tr, dict):
            since = tr.get("since")
            until = tr.get("until")
            if since is None or until is None:
                return _err("VALIDATION_ERROR", "time_range dict must include 'since' and 'until' (YYYY-MM-DD)")
            if not isinstance(since, str) or not isinstance(until, str):
                return _err("VALIDATION_ERROR", "time_range.since and time_range.until must be strings")
            try:
                datetime.date.fromisoformat(since)
                datetime.date.fromisoformat(until)
            except ValueError:
                return _err("VALIDATION_ERROR", "time_range.since and time_range.until must be YYYY-MM-DD")
            return {"since": since, "until": until}
        return _err("VALIDATION_ERROR", "time_range must be a string preset, a dict, or null")

    def _append_job(status_value, auth_session_id=None, account_row_id=None, object_id_value=None, time_range_value=None, breakdown_value=None, level_value=None, payload=None, error_message=None, limit_value=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id_value,
            "time_range": time_range_value,
            "breakdown": breakdown_value,
            "level": level_value,
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": limit_value,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    # validation (relaxed: allow null object_id => choose a sensible default for requested level)
    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_job("failed", error_message="access_token must be a non-empty string when provided", payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value={"endpoint": endpoint}, breakdown_value=breakdown, level_value=level)
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")
    if object_id is not None:
        if not isinstance(object_id, str):
            _append_job("failed", error_message="object_id must be a string or null", payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value={"endpoint": endpoint}, breakdown_value=breakdown, level_value=level)
            return _err("VALIDATION_ERROR", "object_id must be a string or null")
        object_id = object_id.strip()
        if object_id == "":
            object_id = None
    if not isinstance(breakdown, str):
        _append_job("failed", error_message="breakdown must be a string", payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value={"endpoint": endpoint}, breakdown_value=None, level_value=level)
        return _err("VALIDATION_ERROR", "breakdown must be a string")
    if not isinstance(level, str):
        _append_job("failed", error_message="level must be a string", payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value={"endpoint": endpoint}, breakdown_value=breakdown, level_value=None)
        return _err("VALIDATION_ERROR", "level must be a string")
    level = level.strip()
    if level not in ("account", "campaign", "adset", "ad"):
        _append_job("failed", error_message="Invalid level", payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value={"endpoint": endpoint}, breakdown_value=breakdown, level_value=level)
        return _err("VALIDATION_ERROR", "level must be one of: account, campaign, adset, ad")

    tr_norm = _normalize_time_range(time_range)
    if isinstance(tr_norm, dict) and tr_norm.get("error"):
        _append_job("failed", error_message=tr_norm["error"]["message"], payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value=None, breakdown_value=breakdown, level_value=level)
        return tr_norm

    # auth
    sessions = _load("meta_auth_sessions.json")

    def _session_valid(s):
        if not isinstance(s, dict):
            return False
        if s.get("status") != "active":
            return False
        if not s.get("access_token_ciphertext"):
            return False
        exp = _parse_dt_any(s.get("token_expires_at"))
        if exp is not None and exp <= _now_dt():
            return False
        return True

    resolved = None
    token_mode = "cached"
    if access_token is not None and access_token.strip():
        token_mode = "provided"
        for s in sessions:
            if s.get("id") == access_token or s.get("access_token_ciphertext") == access_token:
                if _session_valid(s):
                    resolved = s
                    break
        if resolved is None:
            for s in sessions:
                if _session_valid(s):
                    resolved = s
                    break
            if resolved is None:
                _append_job("failed", error_message="No valid cached Meta auth session available", payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value=tr_norm, breakdown_value=(breakdown or None), level_value=level)
                return _err("UNAUTHORIZED", "No valid cached Meta auth session available")
    else:
        candidates = [s for s in sessions if _session_valid(s)]
        candidates.sort(key=lambda r: (r.get("last_used_at") or "", r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        resolved = candidates[0] if candidates else None
        if resolved is None:
            _append_job("failed", error_message="No valid cached Meta auth session available", payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value=tr_norm, breakdown_value=(breakdown or None), level_value=level)
            return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    # rate limit
    aa = _load("analytics_and_archive.json")
    window_s = 60
    limit_per_window = 60
    cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in aa:
        if r.get("auth_session_id") != resolved.get("id"):
            continue
        dt = _parse_dt_any(r.get("created_at"))
        if dt is not None and dt >= cutoff:
            recent += 1
    if recent >= limit_per_window:
        _append_job("failed", auth_session_id=resolved.get("id"), error_message="Rate limit exceeded",
                    payload={"recent": recent, "window_s": window_s, "latency_ms": int((time.time()-t0)*1000)},
                    time_range_value=tr_norm, breakdown_value=(breakdown or None), level_value=level)
        return _err("RATE_LIMIT", "Too many requests; please retry later", window_s=window_s, limit=limit_per_window)

    # object resolution: if object_id omitted, choose latest object matching level within accessible accounts
    accounts = _load("ad_accounts.json")
    objs = _load("ad_objects.json")
    session_account_ids = {a.get("id") for a in accounts if a.get("auth_session_id") == resolved.get("id")}
    if not session_account_ids:
        session_account_ids = {a.get("id") for a in accounts}  # fallback to any

    resolved_account_row_id = None
    chosen_object_id = object_id

    if chosen_object_id is None:
        if level == "account":
            # use external_meta_account_id if available
            cand = [a for a in accounts if a.get("id") in session_account_ids]
            cand.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
            if not cand:
                _append_job("failed", auth_session_id=resolved.get("id"), error_message="No account available for insights",
                            payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value=tr_norm, breakdown_value=(breakdown or None), level_value=level)
                return _err("NOT_FOUND", "No ad account available in local cache to query insights")
            chosen_object_id = cand[0].get("external_meta_account_id") or cand[0].get("id")
            resolved_account_row_id = cand[0].get("id")
        else:
            ot = {"campaign": "campaign", "adset": "adset", "ad": "ad"}[level]
            cand = [o for o in objs if o.get("object_type") == ot and o.get("account_id") in session_account_ids and o.get("status") != "deleted"]
            cand.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
            if not cand:
                _append_job("failed", auth_session_id=resolved.get("id"), error_message="No object available for insights",
                            payload={"latency_ms": int((time.time()-t0)*1000)}, time_range_value=tr_norm, breakdown_value=(breakdown or None), level_value=level)
                return _err("NOT_FOUND", f"No {level} available in local cache to query insights")
            chosen_object_id = cand[0].get("external_meta_id") or cand[0].get("id")
            resolved_account_row_id = cand[0].get("account_id")
    else:
        # determine account_row_id if possible
        if level == "account":
            for a in accounts:
                if a.get("external_meta_account_id") == chosen_object_id or a.get("id") == chosen_object_id:
                    resolved_account_row_id = a.get("id")
                    break
        else:
            for o in objs:
                if o.get("external_meta_id") == chosen_object_id or o.get("id") == chosen_object_id:
                    resolved_account_row_id = o.get("account_id")
                    break

    # cache TTL: repeated identical queries within 120s served from latest succeeded result_payload
    query_key = hashlib.sha256(json.dumps({
        "object_id": chosen_object_id,
        "time_range": tr_norm,
        "breakdown": breakdown.strip() or None,
        "level": level
    }, sort_keys=True).encode("utf-8")).hexdigest()

    latest = None
    ttl_s = 120
    now_dt = _now_dt()
    for r in aa:
        if r.get("job_type") != "insights_query":
            continue
        if r.get("status") != "succeeded":
            continue
        rp = r.get("result_payload") or {}
        if isinstance(rp, dict) and rp.get("query_key") == query_key:
            dt = _parse_dt_any(r.get("created_at"))
            if dt is None:
                continue
            if latest is None or dt > latest[0]:
                latest = (dt, r)
    if latest is not None and (now_dt - latest[0]).total_seconds() <= ttl_s:
        payload = latest[1].get("result_payload") or {}
        _append_job("succeeded", auth_session_id=resolved.get("id"), account_row_id=resolved_account_row_id,
                    object_id_value=chosen_object_id, time_range_value=tr_norm, breakdown_value=(breakdown.strip() or None), level_value=level,
                    payload={"served_from_cache": True, "query_key": query_key, "cached_at": latest[0].isoformat().replace("+00:00", "Z"), "latency_ms": int((time.time()-t0)*1000)})
        return {"data": payload.get("rows", []), "cached": True, "query": {"object_id": chosen_object_id, "time_range": tr_norm, "breakdown": breakdown.strip() or None, "level": level}}

    # produce deterministic offline "insights" rows
    # (We do not fabricate Meta responses beyond plausible fields; still store to analytics_and_archive as required.)
    rows = []
    # one row summary
    rows.append({
        "object_id": chosen_object_id,
        "level": level,
        "date_start": (tr_norm.get("since") if "since" in tr_norm else None),
        "date_stop": (tr_norm.get("until") if "until" in tr_norm else None),
        "impressions": "0",
        "clicks": "0",
        "spend": "0.00",
        "currency": None,
        "breakdown": breakdown.strip() or None
    })

    result_payload = {
        "query_key": query_key,
        "rows": rows,
        "paging": {"cursors": None, "next": None},
        "served_from_cache": False,
        "token_mode": token_mode
    }

    _append_job("succeeded", auth_session_id=resolved.get("id"), account_row_id=resolved_account_row_id,
                object_id_value=chosen_object_id, time_range_value=tr_norm, breakdown_value=(breakdown.strip() or None), level_value=level,
                payload=result_payload, error_message=None, limit_value=None)

    # update session last_used_at
    now_iso = _now_iso()
    for s in sessions:
        if s.get("id") == resolved.get("id"):
            s["last_used_at"] = now_iso
            s["updated_at"] = now_iso
            break
    _save("meta_auth_sessions.json", sessions)

    return {"data": rows, "cached": False, "query": {"object_id": chosen_object_id, "time_range": tr_norm, "breakdown": breakdown.strip() or None, "level": level}}

def debug_image_download(access_token=None, url="", ad_id="", **_extra):
    import json, os, datetime, time, uuid, urllib.request, urllib.error
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "debug_image_download"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_job(status_value, auth_session_id=None, account_row_id=None, object_id=None, url_value=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        job = {
            "id": _gen_id("aa"),
            "job_type": "image_download_debug",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id,
            "time_range": None,
            "breakdown": None,
            "level": None,
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": url_value,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        rows.append(job)
        _save("analytics_and_archive.json", rows)
        return job

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        now = _now_dt()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("auth_session_id") != auth_session_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    # Relax validation per audit defect: accept empty url/ad_id, but still persist a debug row and return diagnostics.
    if url is None:
        url = ""
    if ad_id is None:
        ad_id = ""
    if not isinstance(url, str) or not isinstance(ad_id, str):
        _append_job("failed", object_id=ad_id or None, url_value=url if isinstance(url, str) else None, error_message="url and ad_id must be strings")
        return _err("VALIDATION_ERROR", "url and ad_id must be strings")

    # Resolve auth only if needed. If url is non-empty, no auth required. If resolving by ad_id, auth required.
    need_auth = (url.strip() == "")

    auth_rows = _load("meta_auth_sessions.json")
    now_dt = _now_dt()

    def _is_session_usable(s):
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp and exp <= now_dt:
            return False
        return True

    auth_session = None
    if need_auth:
        if access_token is not None:
            if not isinstance(access_token, str):
                _append_job("failed", object_id=ad_id or None, url_value=url or None, error_message="access_token must be a string")
                return _err("VALIDATION_ERROR", "access_token must be a string")
            for s in auth_rows:
                if not _is_session_usable(s):
                    continue
                if access_token == s.get("id") or access_token == s.get("access_token_ciphertext"):
                    auth_session = s
                    break
            if auth_session is None:
                auth_session = {"id": None}
        else:
            for s in auth_rows:
                if _is_session_usable(s):
                    auth_session = s
                    break
            if auth_session is None:
                job = _append_job("failed", object_id=ad_id or None, url_value=url or None, error_message="No active Meta auth session available")
                return _err("UNAUTHORIZED", "No active Meta auth session available")
    else:
        # If only fetching direct URL, still optionally attach an auth session for rate limiting/audit if exists.
        for s in auth_rows:
            if _is_session_usable(s):
                auth_session = s
                break
        if auth_session is None:
            auth_session = {"id": None}

    ok, rl_err = _rate_limit_check(auth_session.get("id"))
    if not ok:
        _append_job("failed", auth_session_id=auth_session.get("id"), object_id=ad_id or None, url_value=url or None, error_message=rl_err["error"]["message"])
        return rl_err

    # Resolve URL from ad_id if needed and possible
    resolved_url = url.strip() if isinstance(url, str) else ""
    account_row_id = None
    if resolved_url == "" and ad_id.strip() != "":
        objs = _load("ad_objects.json")
        ad_row = None
        for r in objs:
            if r.get("object_type") == "ad" and (r.get("external_meta_id") == ad_id or r.get("id") == ad_id):
                ad_row = r
                break
        if ad_row:
            account_row_id = ad_row.get("account_id")
            # try creative_assets snapshot_url, else creative raw payload
            assets = _load("creative_assets.json")
            snap = None
            for a in assets:
                if a.get("asset_type") == "ad_image_snapshot" and a.get("status") in ("active", "processing", "failed") and isinstance(a.get("raw_meta_payload"), dict):
                    if a["raw_meta_payload"].get("ad_id") == (ad_row.get("external_meta_id") or ad_row.get("id")):
                        snap = a
                        break
            if snap and snap.get("snapshot_url"):
                resolved_url = snap.get("snapshot_url")
            else:
                # fallback: if creative asset exists with snapshot_url
                for a in assets:
                    if a.get("asset_type") == "ad_creative" and a.get("external_meta_id") == ad_row.get("creative_external_id") and a.get("raw_meta_payload"):
                        # some payloads include snapshot_url; otherwise none
                        if isinstance(a["raw_meta_payload"], dict) and a["raw_meta_payload"].get("snapshot_url"):
                            resolved_url = a["raw_meta_payload"]["snapshot_url"]
                            break

    diagnostics = {
        "requested": {"url": url, "ad_id": ad_id},
        "resolved_url": resolved_url if resolved_url != "" else None,
        "attempted_fetch": False,
        "http": None,
        "error": None
    }

    # Offline-friendly: attempt fetch only if a non-empty URL exists and is http(s)
    if resolved_url and resolved_url.startswith(("http://", "https://")):
        diagnostics["attempted_fetch"] = True
        req = urllib.request.Request(resolved_url, headers={"User-Agent": "MetaAdsInterface/1.0"})
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = resp.read(1024 * 256)  # cap for diagnostics
                diagnostics["http"] = {
                    "status": getattr(resp, "status", None),
                    "reason": getattr(resp, "reason", None),
                    "headers": dict(resp.headers.items()),
                    "sample_bytes": len(data),
                    "content_type": resp.headers.get("Content-Type"),
                    "content_length": resp.headers.get("Content-Length")
                }
        except urllib.error.HTTPError as e:
            diagnostics["http"] = {
                "status": e.code,
                "reason": str(e.reason),
                "headers": dict(e.headers.items()) if getattr(e, "headers", None) else None
            }
            diagnostics["error"] = {"type": "HTTPError", "message": str(e)}
        except urllib.error.URLError as e:
            diagnostics["error"] = {"type": "URLError", "message": str(e.reason)}
        except TimeoutError as e:
            diagnostics["error"] = {"type": "TimeoutError", "message": str(e)}
        except ValueError as e:
            diagnostics["error"] = {"type": "ValueError", "message": str(e)}
    else:
        if resolved_url == "":
            diagnostics["error"] = {"type": "NoTarget", "message": "No url provided and ad_id could not be resolved to a snapshot_url"}
        else:
            diagnostics["error"] = {"type": "UnsupportedURL", "message": "Only http(s) urls can be fetched in this environment"}

    status_value = "succeeded" if diagnostics.get("http") and diagnostics["http"].get("status") and 200 <= diagnostics["http"]["status"] < 400 else "failed"
    job = _append_job(
        status_value,
        auth_session_id=auth_session.get("id"),
        account_row_id=account_row_id,
        object_id=ad_id.strip() or None,
        url_value=resolved_url or (url.strip() or None),
        payload=diagnostics,
        error_message=(diagnostics.get("error") or {}).get("message")
    )

    # Touch auth session last_used_at if real session used
    if auth_session.get("id"):
        for s in auth_rows:
            if s.get("id") == auth_session["id"]:
                s["last_used_at"] = _now_iso()
                s["updated_at"] = _now_iso()
                break
        _save("meta_auth_sessions.json", auth_rows)

    return {"job": job, "diagnostics": diagnostics, "latency_ms": int((time.time() - t0) * 1000)}

def save_ad_image_via_api(access_token=None, ad_id=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "save_ad_image_via_api"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, account_row_id=None, object_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "image_download_debug",
            "auth_session_id": auth_session_id,
            "account_id": account_row_id,
            "object_id": object_id or (ad_id if ad_id else endpoint),
            "time_range": None,
            "breakdown": None,
            "level": None,
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    def _resolve_session(token_param):
        sessions = _load("meta_auth_sessions.json")

        def _valid(s):
            if not isinstance(s, dict):
                return False
            if s.get("status") != "active":
                return False
            exp = _parse_dt_any(s.get("token_expires_at"))
            if exp is not None and exp <= _now_dt():
                return False
            if not s.get("access_token_ciphertext"):
                return False
            return True

        if token_param is not None:
            if not isinstance(token_param, str) or not token_param.strip():
                return None
            tok = token_param.strip()
            for s in sessions:
                if (s.get("id") == tok or s.get("access_token_ciphertext") == tok) and _valid(s):
                    return s
            return None

        for s in sessions:
            if _valid(s):
                return s
        return None

    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")
    if ad_id is not None and (not isinstance(ad_id, str) or not ad_id.strip()):
        _append_audit("failed", error_message="ad_id must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "ad_id must be a non-empty string when provided")
    ad_id = ad_id.strip() if isinstance(ad_id, str) else None

    session = _resolve_session(access_token)
    if session is None:
        _append_audit("failed", error_message="No valid cached Meta auth session available", payload={"endpoint": endpoint, "ad_id": ad_id})
        return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    objs = _load("ad_objects.json")
    assets = _load("creative_assets.json")

    # resolve ad (allow null by choosing latest)
    ad_row = None
    if ad_id:
        ad_row = next((r for r in objs if r.get("object_type") == "ad" and (r.get("external_meta_id") == ad_id or r.get("id") == ad_id)), None)
    else:
        candidates = [r for r in objs if r.get("object_type") == "ad"]
        candidates.sort(key=lambda r: _parse_dt_any(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=True)
        ad_row = candidates[0] if candidates else None
        ad_id = ad_row.get("external_meta_id") if ad_row else None

    if ad_row is None:
        _append_audit("failed", auth_session_id=session.get("id"), error_message="Ad not found", payload={"endpoint": endpoint, "ad_id": ad_id})
        return _err("NOT_FOUND", "Ad not found", ad_id=ad_id)

    acct_row_id = ad_row.get("account_id")
    now = _now_iso()

    # find/create snapshot asset for ad and set a placeholder "api saved" local file
    snap = next((a for a in assets if a.get("asset_type") == "ad_image_snapshot" and isinstance(a.get("raw_meta_payload"), dict) and a.get("raw_meta_payload", {}).get("ad_id") == ad_row.get("external_meta_id")), None)
    if snap is None:
        snap = {
            "id": "meta_asset_" + uuid.uuid4().hex,
            "account_id": acct_row_id,
            "asset_type": "ad_image_snapshot",
            "external_meta_id": None,
            "name": None,
            "page_id": None,
            "instagram_actor_id": None,
            "image_hash": None,
            "image_source_path": None,
            "snapshot_url": None,
            "local_file_path": None,
            "output_dir": None,
            "mime_type": None,
            "byte_size": None,
            "link_url": None,
            "message": None,
            "headline": None,
            "description": None,
            "call_to_action_type": None,
            "raw_meta_payload": {"ad_id": ad_row.get("external_meta_id"), "creative_external_id": ad_row.get("creative_external_id"), "method": "save_ad_image_via_api"},
            "status": "processing",
            "failure_reason": None,
            "created_at": now,
            "updated_at": now
        }
        assets.append(snap)

    out_dir = os.path.join("ad_images", "via_api")
    try:
        os.makedirs(out_dir, exist_ok=True)
        file_path = os.path.join(out_dir, f"{ad_row.get('external_meta_id')}.img")
        with open(file_path, "wb") as f:
            f.write(b"")  # placeholder
        snap["local_file_path"] = file_path
        snap["output_dir"] = out_dir
        snap["status"] = "active"
        snap["failure_reason"] = None
        snap["updated_at"] = _now_iso()
        _save("creative_assets.json", assets)
        _append_audit("succeeded", auth_session_id=session.get("id"), account_row_id=acct_row_id, object_id=ad_row.get("external_meta_id"), payload={"latency_ms": int((time.time() - t0) * 1000), "local_file_path": file_path})
        return {"ad_id": ad_row.get("external_meta_id"), "local_file_path": file_path, "latency_ms": int((time.time() - t0) * 1000)}
    except Exception:
        snap["status"] = "failed"
        snap["failure_reason"] = "Failed to save image via API (offline placeholder write failed)"
        snap["updated_at"] = _now_iso()
        _save("creative_assets.json", assets)
        _append_audit("failed", auth_session_id=session.get("id"), account_row_id=acct_row_id, object_id=ad_row.get("external_meta_id"), error_message=snap["failure_reason"], payload={"latency_ms": int((time.time() - t0) * 1000)})
        return _err("CONFLICT", "Failed to save image via API", failure_reason=snap["failure_reason"])

def search_ads_archive(access_token=None, search_terms=None, ad_type=None, ad_reached_countries=None, limit=None, fields=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_ads_archive"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_job(status_value, auth_session_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        job = {
            "id": _gen_id("aa"),
            "job_type": "ads_archive_search",
            "auth_session_id": auth_session_id,
            "account_id": None,
            "object_id": None,
            "time_range": None,
            "breakdown": None,
            "level": None,
            "search_terms": search_terms,
            "ad_type": ad_type,
            "ad_reached_countries": ad_reached_countries,
            "fields": fields,
            "limit": limit,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        }
        rows.append(job)
        _save("analytics_and_archive.json", rows)
        return job

    def _rate_limit_check(auth_session_id):
        aa = _load("analytics_and_archive.json")
        now = _now_dt()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in aa:
            if r.get("auth_session_id") != auth_session_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= limit_per_window:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    # Validate required inputs per schema constraints: search_terms not null, ad_type not null
    if search_terms is None or (isinstance(search_terms, str) and search_terms.strip() == ""):
        _append_job("failed", error_message="search_terms is required")
        return _err("VALIDATION_ERROR", "search_terms is required", search_terms=search_terms)
    if not isinstance(search_terms, str):
        _append_job("failed", error_message="search_terms must be a string")
        return _err("VALIDATION_ERROR", "search_terms must be a string")

    if ad_type is None:
        ad_type = "ALL"
    if not isinstance(ad_type, str):
        _append_job("failed", error_message="ad_type must be a string")
        return _err("VALIDATION_ERROR", "ad_type must be a string")

    if ad_reached_countries is not None:
        if not isinstance(ad_reached_countries, list) or any(not isinstance(x, str) for x in ad_reached_countries):
            _append_job("failed", error_message="ad_reached_countries must be an array of strings")
            return _err("VALIDATION_ERROR", "ad_reached_countries must be an array of strings")

    # limit bounds (1..500)
    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        _append_job("failed", error_message="limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        _append_job("failed", error_message="limit must be between 1 and 500")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500", limit=limit)

    if fields is None:
        fields = "ad_creation_time,ad_creative_body,ad_snapshot_url"
    if not isinstance(fields, str):
        _append_job("failed", error_message="fields must be a string")
        return _err("VALIDATION_ERROR", "fields must be a string")

    # Resolve auth (optional in param; required by business rule if no access_token: find active session)
    auth_rows = _load("meta_auth_sessions.json")
    now_dt = _now_dt()

    def _is_session_usable(s):
        if s.get("status") != "active":
            return False
        exp = _parse_dt(s.get("token_expires_at"))
        if exp and exp <= now_dt:
            return False
        return True

    auth_session = None
    if access_token is not None:
        if not isinstance(access_token, str):
            _append_job("failed", error_message="access_token must be a string")
            return _err("VALIDATION_ERROR", "access_token must be a string")
        for s in auth_rows:
            if not _is_session_usable(s):
                continue
            if access_token == s.get("id") or access_token == s.get("access_token_ciphertext"):
                auth_session = s
                break
        if auth_session is None:
            auth_session = {"id": None}
    else:
        for s in auth_rows:
            if _is_session_usable(s):
                auth_session = s
                break
        if auth_session is None:
            _append_job("failed", error_message="No active Meta auth session available")
            return _err("UNAUTHORIZED", "No active Meta auth session available")

    ok, rl_err = _rate_limit_check(auth_session.get("id"))
    if not ok:
        _append_job("failed", auth_session_id=auth_session.get("id"), error_message=rl_err["error"]["message"])
        return rl_err

    # Offline behavior: return a deterministic synthetic result set derived from stored objects/creatives when possible.
    # We must not fabricate rows that were not read from store; so we only return items if we can map them to stored data.
    # We'll search creative_assets/ad_objects names/messages for the search_terms.
    terms = search_terms.strip().lower()
    assets = _load("creative_assets.json")
    objs = _load("ad_objects.json")

    # Index ad_id -> snapshot_url when available
    ad_snap = {}
    for a in assets:
        if a.get("asset_type") == "ad_image_snapshot" and a.get("snapshot_url") and isinstance(a.get("raw_meta_payload"), dict):
            adid = a["raw_meta_payload"].get("ad_id")
            if adid:
                ad_snap[adid] = a.get("snapshot_url")

    results = []
    for o in objs:
        if o.get("object_type") != "ad":
            continue
        hay = " ".join([str(o.get("name") or ""), str(o.get("external_meta_id") or ""), str(o.get("creative_external_id") or "")]).lower()
        if terms and terms not in hay:
            continue
        item = {
            "ad_id": o.get("external_meta_id"),
            "ad_name": o.get("name"),
            "ad_snapshot_url": ad_snap.get(o.get("external_meta_id")),
            "page_id": None,
            "page_name": None
        }
        results.append(item)
        if len(results) >= limit:
            break

    payload = {"data": results, "paging": {"cursors": None, "next": None}}
    job = _append_job("succeeded", auth_session_id=auth_session.get("id"), payload=payload, error_message=None)

    # Touch auth session last_used_at
    if auth_session.get("id"):
        now = _now_iso()
        for s in auth_rows:
            if s.get("id") == auth_session["id"]:
                s["last_used_at"] = now
                s["updated_at"] = now
                break
        _save("meta_auth_sessions.json", auth_rows)

    return {"job": job, "results": results, "limit": limit, "latency_ms": int((time.time() - t0) * 1000)}

def create_meta_auth_session(access_token, token_source=None, principal_type=None, principal_id=None, scopes=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate
    if not isinstance(access_token, str) or not access_token.strip():
        return _err("VALIDATION_ERROR", "access_token is required and must be a non-empty string")

    if token_source is None:
        token_source = "manual"
    if token_source not in ("manual", "oauth_login_link", "system_import"):
        return _err("VALIDATION_ERROR", "token_source must be one of: manual, oauth_login_link, system_import")

    if principal_type is not None and principal_type not in ("user", "service"):
        return _err("VALIDATION_ERROR", "principal_type must be one of: user, service")

    if principal_id is not None and (not isinstance(principal_id, str) or not principal_id.strip()):
        return _err("VALIDATION_ERROR", "principal_id must be a non-empty string when provided")

    if scopes is not None:
        if (not isinstance(scopes, list)) or any((not isinstance(s, str) or not s.strip()) for s in scopes):
            return _err("VALIDATION_ERROR", "scopes must be an array of non-empty strings")

    # "Validate token" offline: require minimal shape and infer scopes.
    # Real service would introspect. Here: refuse if token too short / obviously invalid.
    if len(access_token.strip()) < 10:
        return _err("UNAUTHORIZED", "Token validation failed")

    inferred_scopes = scopes if scopes is not None else ["ads_read"]
    # derive meta_user_id if user session: embed stable pseudo-id from token
    meta_user_id = None
    if principal_type == "user":
        meta_user_id = "me_" + uuid.uuid5(uuid.NAMESPACE_DNS, access_token.strip()).hex[:12]

    # Map vendor tool token_source values -> schema token_source enum
    schema_token_source = {
        "manual": "provided_by_client",
        "oauth_login_link": "oauth_login",
        "system_import": "pipeboard",
    }[token_source]

    sessions = _load("meta_auth_sessions.json")

    # If no principal provided, bind to an ambient default principal (service)
    if principal_type is None:
        principal_type = "service"
    if principal_id is None:
        principal_id = "ambient"

    # Enforce uniqueness: only one active per (principal_type, principal_id)
    # If exists active, idempotently rotate token (update ciphertext/scopes/updated_at) and keep same row active.
    def _parse_dt(s):
        if not s: return None
        try:
            if isinstance(s, str) and s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    existing_active = None
    for s in sessions:
        if s.get("principal_type") == principal_type and s.get("principal_id") == principal_id and s.get("status") == "active":
            existing_active = s
            break

    # Ciphertext placeholder (we never store plaintext)
    ciphertext = "ciphertext:" + uuid.uuid5(uuid.NAMESPACE_DNS, access_token.strip()).hex

    if existing_active:
        # token_expires_at constraint: null or > created_at. We'll keep null.
        existing_active["access_token_ciphertext"] = ciphertext
        existing_active["token_source"] = schema_token_source
        existing_active["scopes"] = inferred_scopes
        existing_active["meta_user_id"] = meta_user_id or existing_active.get("meta_user_id")
        existing_active["status"] = "active"
        existing_active["last_used_at"] = now
        existing_active["updated_at"] = now
        _save("meta_auth_sessions.json", sessions)
        latency_ms = int((time.time() - t0) * 1000)
        return {"session": existing_active, "meta": {"latency_ms": latency_ms, "idempotent": True}}

    # Create new session
    new_id = "mas_" + uuid.uuid4().hex
    row = {
        "id": new_id,
        "principal_type": principal_type,
        "principal_id": principal_id,
        "meta_user_id": meta_user_id,
        "access_token_ciphertext": ciphertext,
        "token_source": schema_token_source,
        "scopes": inferred_scopes,
        "token_expires_at": None,
        "status": "active",
        "last_used_at": now,
        "last_login_link_url": None,
        "last_login_link_expires_at": None,
        "created_at": now,
        "updated_at": now,
    }
    sessions.append(row)
    _save("meta_auth_sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    return {"session": row, "meta": {"latency_ms": latency_ms, "idempotent": False}}

def get_whoami(access_token=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
