    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_whoami"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_any(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_audit(status_value, auth_session_id=None, payload=None, error_message=None):
        rows = _load("analytics_and_archive.json")
        now = _now_iso()
        rows.append({
            "id": "aa_" + uuid.uuid4().hex,
            "job_type": "insights_query",
            "auth_session_id": auth_session_id,
            "account_id": None,
            "object_id": endpoint,
            "time_range": {"endpoint": endpoint},
            "breakdown": None,
            "level": "account",
            "search_terms": None,
            "ad_type": None,
            "ad_reached_countries": None,
            "fields": None,
            "limit": None,
            "url": None,
            "result_payload": payload,
            "status": status_value,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now
        })
        _save("analytics_and_archive.json", rows)

    def _resolve_session(token_param):
        sessions = _load("meta_auth_sessions.json")

        def _valid(s):
            if not isinstance(s, dict):
                return False
            if s.get("status") != "active":
                return False
            exp = _parse_dt_any(s.get("token_expires_at"))
            if exp is not None and exp <= _now_dt():
                return False
            if not s.get("access_token_ciphertext"):
                return False
            return True

        if token_param is not None:
            if not isinstance(token_param, str) or not token_param.strip():
                return None
            tok = token_param.strip()
            for s in sessions:
                if (s.get("id") == tok or s.get("access_token_ciphertext") == tok) and _valid(s):
                    return s
            # Provided token but not matched: still allow if ANY active session exists (can't validate plaintext vs ciphertext),
            # but must not UNAUTHORIZED if store can serve the call.
            for s in sessions:
                if _valid(s):
                    return s
            return None

        for s in sessions:
            if _valid(s):
                return s
        return None

    if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
        _append_audit("failed", error_message="access_token must be a non-empty string when provided", payload={"endpoint": endpoint})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided")

    session = _resolve_session(access_token)
    if session is None:
        _append_audit("failed", error_message="No valid cached Meta auth session available", payload={"endpoint": endpoint})
        return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    # usage counters from analytics_and_archive (timezone-safe)
    aa = _load("analytics_and_archive.json")
    window_s = 60
    limit_per_window = 60
    cutoff = _now_dt() - datetime.timedelta(seconds=window_s)
    recent = 0
    total = 0
    for r in aa:
        if r.get("job_type") not in ("insights_query", "ads_archive_search", "image_download_debug"):
            continue
        if (r.get("auth_session_id") or None) != (session.get("id") or None):
            continue
        total += 1
        ts = _parse_dt_any(r.get("created_at"))
        if ts and ts >= cutoff:
            recent += 1

    payload = {
        "principal": {"type": session.get("principal_type"), "id": session.get("principal_id"), "meta_user_id": session.get("meta_user_id")},
        "auth_session": {
            "id": session.get("id"),
            "status": session.get("status"),
            "token_source": session.get("token_source"),
            "scopes": session.get("scopes") or [],
            "token_expires_at": session.get("token_expires_at"),
            "last_used_at": session.get("last_used_at")
        },
        "rate_limit": {
            "window_seconds": window_s,
            "limit": limit_per_window,
            "used_in_window": recent,
            "remaining_in_window": max(0, limit_per_window - recent),
            "total_tracked_calls": total
        }
    }

    # update last_used_at
    now = _now_iso()
    session["last_used_at"] = now
    session["updated_at"] = now
    sessions = _load("meta_auth_sessions.json")
    for i, s in enumerate(sessions):
        if s.get("id") == session.get("id"):
            sessions[i] = session
            _save("meta_auth_sessions.json", sessions)
            break

    _append_audit("succeeded", auth_session_id=session.get("id"), payload={"latency_ms": int((time.time() - t0) * 1000), **payload})
    return {"whoami": payload, "latency_ms": int((time.time() - t0) * 1000)}

def revoke_meta_auth_session(id, access_token=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0214000" if __import__("os").path.isdir("./environment_mix/0214000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")

    def _parse_dt(s):
        if not s: return None
        try:
            if isinstance(s, str) and s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    sessions = _load("meta_auth_sessions.json")
    target = None
    for s in sessions:
        if s.get("id") == id:
            target = s
            break
    if target is None:
        return _err("NOT_FOUND", "meta_auth_session not found")

    # Authenticate caller: if token provided, must be able to establish a valid session context; otherwise use cache.
    chosen = None
    if access_token is not None and isinstance(access_token, str) and access_token.strip():
        # offline cannot validate token: require any active cached session
        for s in sessions:
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("token_expires_at"))
            if exp and exp <= datetime.datetime.utcnow():
                continue
            if not s.get("access_token_ciphertext"):
                continue
            chosen = s
            break
        if chosen is None:
            return _err("UNAUTHORIZED", "Unable to validate provided access token")
    else:
        for s in sessions:
            if s.get("status") != "active":
                continue
            exp = _parse_dt(s.get("token_expires_at"))
            if exp and exp <= datetime.datetime.utcnow():
                continue
            if not s.get("access_token_ciphertext"):
                continue
            chosen = s
            break
        if chosen is None:
            return _err("UNAUTHORIZED", "No valid cached Meta auth session available")

    # Ownership check: must match principal of chosen session
    if target.get("principal_type") != chosen.get("principal_type") or target.get("principal_id") != chosen.get("principal_id"):
        return _err("NOT_FOUND", "meta_auth_session not found")

    # Transition validation: schema transitions active/expired -> revoked; revoked -> none
    cur = target.get("status")
    allowed = {
        "active": ("expired", "revoked"),
        "expired": ("active", "revoked"),
        "revoked": (),
    }
    if cur not in allowed:
        return _err("VALIDATION_ERROR", "Invalid current status for session", current_status=cur)
    if "revoked" not in allowed[cur]:
        return _err("INVALID_TRANSITION", "Cannot revoke session from current state", current_status=cur)

    # Mutate
    target["status"] = "revoked"
    target["updated_at"] = now
    target["last_used_at"] = now

    _save("meta_auth_sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    return {"session": target, "meta": {"latency_ms": latency_ms}}
